const fs=require('fs'),path=require('path'),{execSync}=require('child_process');
const files={"backend/prisma/schema.prisma":"// prisma/schema.prisma\n// DropOS - Full Multi-Tenant SaaS Schema\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ─── Enums ───────────────────────────────────────────────────────────────────\n\nenum Role {\n  SUPER_ADMIN\n  STORE_OWNER\n  CUSTOMER\n}\n\nenum UserStatus {\n  ACTIVE\n  SUSPENDED\n  PENDING_VERIFICATION\n  BANNED\n}\n\nenum PlanType {\n  STARTER\n  PRO\n  ADVANCED\n}\n\nenum StoreStatus {\n  ACTIVE\n  SUSPENDED\n  PENDING\n  ARCHIVED\n}\n\nenum ProductStatus {\n  ACTIVE\n  DRAFT\n  OUT_OF_STOCK\n  ARCHIVED\n}\n\nenum OrderStatus {\n  PENDING\n  PROCESSING\n  SHIPPED\n  DELIVERED\n  COMPLETED\n  CANCELLED\n  REFUNDED\n}\n\nenum PaymentStatus {\n  PENDING\n  SUCCESS\n  FAILED\n  REFUNDED\n  DISPUTED\n}\n\nenum PaymentGateway {\n  STRIPE\n  PAYSTACK\n  FLUTTERWAVE\n}\n\nenum SubscriptionStatus {\n  ACTIVE\n  CANCELLED\n  EXPIRED\n  PAST_DUE\n}\n\nenum SupportStatus {\n  OPEN\n  IN_PROGRESS\n  RESOLVED\n  CLOSED\n}\n\nenum Priority {\n  LOW\n  MEDIUM\n  HIGH\n  URGENT\n}\n\nenum LogLevel {\n  INFO\n  WARN\n  ERROR\n  CRITICAL\n}\n\n// ─── User ────────────────────────────────────────────────────────────────────\n\nmodel User {\n  id                String     @id @default(uuid())\n  email             String     @unique\n  password          String\n  name              String\n  phone             String?\n  avatar            String?\n  role              Role       @default(STORE_OWNER)\n  status            UserStatus @default(PENDING_VERIFICATION)\n  emailVerified     Boolean    @default(false)\n  emailVerifyToken  String?\n  passwordResetToken String?\n  passwordResetExpiry DateTime?\n  twoFAEnabled      Boolean    @default(false)\n  twoFASecret       String?\n  lastLogin         DateTime?\n  loginAttempts     Int        @default(0)\n  lockedUntil       DateTime?\n  refreshToken      String?\n  adminNotes        String?\n  flags             String[]   @default([])\n  onboarded         Boolean    @default(false)\n  onboardNiche      String?\n  onboardStage      String?\n  onboardGoal       String?\n  onboardTemplate   String?\n  country           String?\n  city              String?\n  timezone          String?    @default(\"UTC\")\n  createdAt         DateTime   @default(now())\n  updatedAt         DateTime   @updatedAt\n\n  // Relations\n  stores            Store[]\n  kaiConversations  KaiConversation[]\n  subscription      Subscription?\n  supportTickets    SupportTicket[]\n  notifications     Notification[]\n  auditLogs         AuditLog[]\n  pushSubscriptions PushSubscription[]\n  referral          Referral?\n  refreshTokens     RefreshToken[]\n\n  @@index([email])\n  @@index([role])\n  @@index([status])\n  @@map(\"users\")\n}\n\n// ─── Store ───────────────────────────────────────────────────────────────────\n\nmodel Store {\n  id              String      @id @default(uuid())\n  ownerId         String\n  name            String\n  slug            String      @unique\n  description     String?\n  logo            String?\n  banner          String?\n  domain          String?     @unique\n  customDomain    String?     @unique\n  templateId      String?\n  paystackConnected Boolean  @default(false)\n  status          StoreStatus @default(PENDING)\n  primaryColor    String?     @default(\"#7c3aed\")\n  accentColor     String?     @default(\"#a855f7\")\n  theme           String?     @default(\"default\")\n  secondaryColor  String?\n  fontFamily      String?     @default(\"DM Sans\")\n  borderRadius    String?     @default(\"rounded\")\n  tagline         String?\n  showReviews     Boolean     @default(true)\n  showInventory   Boolean     @default(true)\n  productsPerRow  Int         @default(4)\n  currency        String      @default(\"USD\")\n  country         String?\n  address         String?\n  supportEmail    String?\n  supportPhone    String?\n  taxRate         Float?      @default(0)\n  shippingEnabled Boolean     @default(true)\n  freeShippingMin Float?\n  metaTitle         String?\n  metaDescription   String?\n  // ── SMS / WhatsApp via Twilio ─────────────────────────────────────────────\n  suppliers           Supplier[]\n  fulfillmentOrders   FulfillmentOrder[]\n\n  // ── Multi-currency ───────────────────────────────────────────────────────────\n  supportedCurrencies Json?       // e.g. [\"USD\",\"EUR\",\"GBP\",\"NGN\"]\n  autoDetectCurrency  Boolean     @default(true)\n  smsEnabled        Boolean     @default(false)\n  smsPhone          String?     // owner's phone for incoming alerts  e.g. +2348012345678\n  whatsappEnabled   Boolean     @default(false)\n  whatsappPhone     String?     // owner's WhatsApp number\n  // ── Live Chat widget ────────────────────────────────────────────────────────\n  liveChatProvider  String?     // \"tawk\", \"crisp\", \"tidio\", \"whatsapp\", or null\n  liveChatId        String?     // Tawk.to property ID / Crisp website ID / Tidio key\n  liveChatEnabled   Boolean     @default(false)\n  notifyOwnerSms    Boolean     @default(true)   // SMS owner on new order\n  notifyCustomerSms Boolean     @default(false)\n  loyaltyEnabled    Boolean     @default(false)\n  themeSettings     Json?  // SMS customer on order + status\n  createdAt         DateTime    @default(now())\n  updatedAt       DateTime    @updatedAt\n\n  // Relations\n  owner           User        @relation(fields: [ownerId], references: [id], onDelete: Cascade)\n  products        Product[]\n  orders          Order[]\n  customers       StoreCustomer[]\n  payments        Payment[]\n  analytics       Analytics[]\n  shippingZones   ShippingZone[]\n  coupons         Coupon[]\n  reviews         Review[]\n  abandonedCarts  AbandonedCart[]\n\n  discounts       Discount[]\n  refunds         Refund[]\n  giftCards       GiftCard[]\n  webhooks        StoreWebhook[]\n  flashSales      FlashSale[]\n  backups         StoreBackup[]\n  apiKeys         ApiKey[]\n  returnRequests  ReturnRequest[]\n  affiliates      Affiliate[]\n  bundles         Bundle[]\n  groupBuys       GroupBuy[]\n  milestones      Milestone[]\n  @@index([ownerId])\n  @@index([slug])\n  @@index([status])\n  @@map(\"stores\")\n  integrations    StoreIntegration[]\n}\n\n// ─── Product ─────────────────────────────────────────────────────────────────\n\nmodel Product {\n  id              String        @id @default(uuid())\n  storeId         String\n  name            String\n  slug            String\n  description     String?\n  price           Float\n  comparePrice    Float?\n  costPrice       Float?\n  sku             String?\n  barcode         String?\n  weight          Float?\n  inventory       Int           @default(0)\n  trackInventory  Boolean       @default(true)\n  allowBackorder  Boolean       @default(false)\n  images          String[]      @default([])\n  category        String?\n  tags            String[]      @default([])\n  status          ProductStatus @default(DRAFT)\n  isDigital       Boolean       @default(false)\n  sourceUrl       String?\n  stockQuantity   Int?\n  metadata        Json?\n  currency        String?\n  metaTitle       String?\n  metaDescription String?\n  createdAt       DateTime      @default(now())\n  updatedAt       DateTime      @updatedAt\n\n  // Relations\n  store           Store         @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  variants        ProductVariant[]\n  orderItems      OrderItem[]\n  reviews         Review[]\n  supplierProducts SupplierProduct[]\n  groupBuys       GroupBuy[]\n\n  @@unique([storeId, slug])\n  @@index([storeId])\n  @@index([status])\n  @@map(\"products\")\n}\n\nmodel ProductVariant {\n  id          String   @id @default(uuid())\n  productId   String\n  name        String\n  value       String\n  price       Float?\n  inventory   Int      @default(0)\n  sku         String?\n  image       String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  product     Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@index([productId])\n  @@map(\"product_variants\")\n}\n\n// ─── Store Customer ──────────────────────────────────────────────────────────\n\nmodel StoreCustomer {\n  id              String    @id @default(uuid())\n  storeId         String\n  email           String\n  name            String\n  phone           String?\n  address         Json?\n  emailVerified   Boolean   @default(false)\n  totalSpent      Float     @default(0)\n  orderCount      Int       @default(0)\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n\n  store           Store     @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  orders          Order[]\n\n  @@unique([storeId, email])\n  @@index([storeId])\n  @@map(\"store_customers\")\n}\n\n// ─── Order ───────────────────────────────────────────────────────────────────\n\nmodel Order {\n  id                String      @id @default(uuid())\n  orderNumber       String      @unique\n  storeId           String\n  customerId        String?\n  customerEmail     String\n  customerName      String\n  customerPhone     String?\n  shippingAddress   Json?\n  billingAddress    Json?\n  status            OrderStatus @default(PENDING)\n  subtotal          Float\n  shippingCost      Float       @default(0)\n  taxAmount         Float       @default(0)\n  discountAmount    Float       @default(0)\n  total             Float\n  currency          String      @default(\"USD\")\n  notes             String?\n  trackingNumber    String?\n  trackingUrl       String?\n  refundAmount      Float?\n  cancelReason      String?\n  fulfillmentStatus String      @default(\"UNFULFILLED\")\n  carrier         String?\n  tax               Float       @default(0)\n  createdAt         DateTime    @default(now())\n  updatedAt         DateTime    @updatedAt\n\n  store             Store         @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  customer          StoreCustomer? @relation(fields: [customerId], references: [id])\n  items             OrderItem[]\n  payment           Payment?\n  refunds           Refund[]\n  returns           ReturnRequest[]\n\n  @@index([storeId])\n  @@index([status])\n  @@index([orderNumber])\n  @@map(\"orders\")\n}\n\nmodel OrderItem {\n  id          String   @id @default(uuid())\n  orderId     String\n  productId   String\n  variantId   String?\n  name        String\n  sku         String?\n  price       Float\n  quantity    Int\n  total       Float\n  image       String?\n  createdAt   DateTime @default(now())\n\n  order       Order    @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  product     Product  @relation(fields: [productId], references: [id])\n\n  @@index([orderId])\n  @@map(\"order_items\")\n}\n\n// ─── Payment ─────────────────────────────────────────────────────────────────\n\nmodel Payment {\n  id                String         @id @default(uuid())\n  orderId           String         @unique\n  storeId           String\n  gateway           PaymentGateway\n  gatewayReference  String?\n  gatewayResponse   Json?\n  amount            Float\n  currency          String         @default(\"USD\")\n  platformFee       Float\n  platformFeePercent Float\n  storeEarnings     Float\n  status            PaymentStatus  @default(PENDING)\n  paidAt            DateTime?\n  refundedAt        DateTime?\n  metadata          Json?\n  createdAt         DateTime       @default(now())\n  updatedAt         DateTime       @updatedAt\n\n  order             Order          @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  store             Store          @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@index([status])\n  @@index([gateway])\n  @@map(\"payments\")\n}\n\n// ─── Subscription ────────────────────────────────────────────────────────────\n\nmodel Subscription {\n  id                  String             @id @default(uuid())\n  userId              String             @unique\n  plan                PlanType           @default(STARTER)\n  status              SubscriptionStatus @default(ACTIVE)\n  currentPeriodStart  DateTime\n  currentPeriodEnd    DateTime\n  cancelAtPeriodEnd   Boolean            @default(false)\n  stripeSubId         String?\n  paystackSubCode     String?\n  price               Float\n  currency            String             @default(\"USD\")\n  createdAt           DateTime           @default(now())\n  updatedAt           DateTime           @updatedAt\n\n  user                User               @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([status])\n  @@map(\"subscriptions\")\n}\n\n// ─── Analytics ───────────────────────────────────────────────────────────────\n\nmodel Analytics {\n  id            String   @id @default(uuid())\n  storeId       String\n  date          DateTime @db.Date\n  views         Int      @default(0)\n  visitors      Int      @default(0)\n  orders        Int      @default(0)\n  revenue       Float    @default(0)\n  conversions   Float    @default(0)\n  avgOrderValue Float    @default(0)\n  newCustomers  Int      @default(0)\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  store         Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@unique([storeId, date])\n  @@index([storeId])\n  @@map(\"analytics\")\n}\n\n// ─── Shipping Zone ───────────────────────────────────────────────────────────\n\n\n// ─── Support Ticket ──────────────────────────────────────────────────────────\n\nmodel SupportTicket {\n  id          String        @id @default(uuid())\n  userId      String\n  subject     String\n  message     String\n  status      SupportStatus @default(OPEN)\n  priority    Priority      @default(MEDIUM)\n  adminReply  String?\n  resolvedAt  DateTime?\n  createdAt   DateTime      @default(now())\n  updatedAt   DateTime      @updatedAt\n\n  user        User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  replies     TicketReply[]\n\n  @@index([userId])\n  @@index([status])\n  @@map(\"support_tickets\")\n}\n\nmodel TicketReply {\n  id        String        @id @default(uuid())\n  ticketId  String\n  senderId  String\n  isAdmin   Boolean       @default(false)\n  message   String\n  createdAt DateTime      @default(now())\n\n  ticket    SupportTicket @relation(fields: [ticketId], references: [id], onDelete: Cascade)\n\n  @@index([ticketId])\n  @@map(\"ticket_replies\")\n}\n\n// ─── Platform Settings ───────────────────────────────────────────────────────\n\nmodel PlatformSettings {\n  id                  String   @id @default(\"singleton\")\n  platformFeePercent  Float    @default(10)\n  starterPrice        Float    @default(9)\n  proPrice            Float    @default(29)\n  advancedPrice       Float    @default(79)\n  maintenanceMode     Boolean  @default(false)\n  allowRegistration   Boolean  @default(true)\n  maxStoresPerOwner   Json     @default(\"{\\\"STARTER\\\":1,\\\"PRO\\\":3,\\\"ADVANCED\\\":999}\")\n  maxProductsPerStore Json     @default(\"{\\\"STARTER\\\":50,\\\"PRO\\\":500,\\\"ADVANCED\\\":999999}\")\n  smtpConfig          Json?\n  updatedAt           DateTime @updatedAt\n\n  @@map(\"platform_settings\")\n}\n\n// ─── Notification ────────────────────────────────────────────────────────────\n\nmodel Notification {\n  id        String   @id @default(uuid())\n  userId    String\n  title     String\n  message   String\n  type      String   @default(\"info\")\n  read      Boolean  @default(false)\n  link      String?\n  createdAt DateTime @default(now())\n\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([read])\n  @@map(\"notifications\")\n}\n\n// ─── Audit Log ───────────────────────────────────────────────────────────────\n\nmodel AuditLog {\n  id          String   @id @default(uuid())\n  userId      String?\n  action      String\n  entity      String\n  entityId    String?\n  oldValues   Json?\n  newValues   Json?\n  ipAddress   String?\n  userAgent   String?\n  level       LogLevel @default(INFO)\n  createdAt   DateTime @default(now())\n\n  user        User?    @relation(fields: [userId], references: [id])\n\n  @@index([userId])\n  @@index([entity])\n  @@index([createdAt])\n  @@map(\"audit_logs\")\n}\n\n// ─── Error Log ───────────────────────────────────────────────────────────────\n\nmodel ErrorLog {\n  id          String   @id @default(uuid())\n  message     String\n  stack       String?\n  path        String?\n  method      String?\n  statusCode  Int?\n  userId      String?\n  ipAddress   String?\n  resolved    Boolean  @default(false)\n  createdAt   DateTime @default(now())\n\n  @@index([resolved])\n  @@index([createdAt])\n  @@map(\"error_logs\")\n}\n\n// ─── Coupon ──────────────────────────────────────────────────────────────────\n\nmodel Coupon {\n  id            String    @id @default(uuid())\n  storeId       String\n  code          String\n  type          String    // PERCENTAGE | FIXED\n  discountType  String?   // alias for type\n  value         Float\n  minOrderValue Float     @default(0)\n  maxUses       Int?\n  usedCount     Int       @default(0)\n  isActive      Boolean   @default(true)\n  expiresAt     DateTime?\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  store         Store     @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@unique([storeId, code])\n  @@index([storeId])\n  @@map(\"coupons\")\n}\n\n// ─── Shipping Zone ───────────────────────────────────────────────────────────\n\nmodel ShippingZone {\n  id            String   @id @default(uuid())\n  storeId       String\n  name          String\n  countries     String[]\n  shippingRate  Float    @default(0)\n  freeThreshold Float?\n  estimatedDays String?\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  store         Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@map(\"shipping_zones\")\n}\n\n// ─── Review ──────────────────────────────────────────────────────────────────\n\nmodel Review {\n  id         String   @id @default(uuid())\n  storeId    String\n  productId  String\n  name       String\n  email      String\n  rating     Int      // 1-5\n  title      String?\n  body       String\n  photos     String[] // array of image URLs\n  approved   Boolean  @default(false)\n  featured   Boolean  @default(false)\n  helpful    Int      @default(0)\n  verified   Boolean  @default(false)\n  orderId    String?  // set if from verified purchase\n  replyBody  String?  // store owner reply\n  repliedAt  DateTime?\n  source     String?  // \"email\" | \"in-app\" | \"import\"\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  store   Store   @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  product Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@index([productId])\n  @@index([storeId])\n  @@map(\"reviews\")\n}\n\n// ─── Abandoned Cart ───────────────────────────────────────────────────────────\n\nmodel AbandonedCart {\n  id            String   @id @default(uuid())\n  storeId       String\n  email         String\n  name          String?\n  items         Json     // CartItem[]\n  total         Float\n  currency      String   @default(\"USD\")\n  token         String   @unique @default(uuid())  // recovery link token\n  recovered     Boolean  @default(false)\n  emailSent     Boolean  @default(false)\n  emailSentAt   DateTime?\n  recoveredAt   DateTime?\n  reminderCount Int      @default(0)\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  store         Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@index([email])\n  @@index([token])\n  @@index([recovered, emailSent])\n  @@map(\"abandoned_carts\")\n}\n\n// ─── Supplier ─────────────────────────────────────────────────────────────────\n\nmodel Supplier {\n  id           String       @id @default(uuid())\n  storeId      String\n  name         String\n  type         SupplierType @default(MANUAL)\n  websiteUrl   String?\n  apiKey       String?\n  apiSecret    String?\n  contactEmail String?\n  contactName  String?\n  notes        String?\n  isActive     Boolean      @default(true)\n  autoFulfill  Boolean      @default(false)  // auto-forward orders when PROCESSING\n  fulfillEmail String?                        // email to send order details to\n  webhookUrl   String?                        // POST order JSON here on new order\n  createdAt    DateTime     @default(now())\n  updatedAt    DateTime     @updatedAt\n\n  store            Store             @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  products         SupplierProduct[]\n  fulfillmentOrders FulfillmentOrder[]\n\n  @@index([storeId])\n  @@map(\"suppliers\")\n}\n\nmodel SupplierProduct {\n  id              String   @id @default(uuid())\n  supplierId      String\n  productId       String\n  supplierSku     String?             // SKU in supplier's system\n  supplierUrl     String?             // original product URL (e.g. AliExpress)\n  supplierPrice   Float?              // cost from supplier (in supplier's currency)\n  supplierCurrency String  @default(\"USD\")\n  processingDays  Int?                // how many days to process\n  shippingDays    Int?                // estimated shipping\n  lastSynced      DateTime?\n  stockStatus     String?             // \"IN_STOCK\" | \"LOW_STOCK\" | \"OUT_OF_STOCK\"\n  priority        Int      @default(1)  // 1 = primary, higher = fallback\n  isActive        Boolean  @default(true)\n  notes           String?             // internal notes\n  createdAt       DateTime @default(now())\n\n  supplier  Supplier @relation(fields: [supplierId], references: [id], onDelete: Cascade)\n  product   Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@unique([supplierId, productId])\n  @@index([productId])\n  @@map(\"supplier_products\")\n}\n\nmodel FulfillmentOrder {\n  id          String            @id @default(uuid())\n  orderId     String\n  supplierId  String\n  storeId     String\n  status      FulfillmentStatus @default(PENDING)\n  sentAt      DateTime?\n  confirmedAt DateTime?\n  notes       String?\n  supplierRef String?           // reference/tracking from supplier\n  method      String?           // \"EMAIL\" | \"WEBHOOK\" | \"MANUAL\"\n  payload     Json?             // what was sent to supplier\n  createdAt   DateTime          @default(now())\n  updatedAt   DateTime          @updatedAt\n\n  supplier Supplier @relation(fields: [supplierId], references: [id])\n  store    Store    @relation(fields: [storeId],    references: [id], onDelete: Cascade)\n\n  @@index([orderId])\n  @@index([supplierId])\n  @@index([storeId])\n  @@map(\"fulfillment_orders\")\n}\n\n\nenum SupplierType {\n  MANUAL\n  ALIEXPRESS\n  CSV\n  WEBHOOK\n}\n\nenum FulfillmentStatus {\n  PENDING\n  SENT\n  CONFIRMED\n  SHIPPED\n  FAILED\n}\n\n\n// ─── Discount Engine ─────────────────────────────────────────────────────────\n\nmodel Discount {\n  id          String       @id @default(uuid())\n  storeId     String\n  name        String\n  description String?\n  type        DiscountType\n  status      DiscountStatus @default(ACTIVE)\n  priority    Int          @default(0)   // higher = applied first\n  stackable   Boolean      @default(false)\n\n  // Trigger conditions\n  minOrderValue    Float?\n  minQuantity      Int?\n  customerTag      String?  // e.g. \"VIP\", \"wholesale\"\n  productIds       String[] // empty = all products\n  collectionIds    String[]\n  firstOrderOnly   Boolean  @default(false)\n\n  // Value / Action\n  valueType   DiscountValueType\n  value       Float             // %, fixed $, or new price\n  maxDiscount Float?            // cap on percentage discounts\n  freeShipping Boolean          @default(false)\n\n  // BOGO fields\n  bogoRequiredQty  Int?         // buy X\n  bogoGetQty       Int?         // get Y\n  bogoPctOff       Float?       // discount on the free item (100 = fully free)\n\n  // Tiered pricing (JSON array of {qty, pct})\n  tiers       Json?            // [{minQty:2,discount:10},{minQty:5,discount:20}]\n\n  // Flash sale\n  flashSaleEndsAt DateTime?\n  flashSaleStartsAt DateTime?\n\n  // Usage limits\n  maxUses       Int?\n  maxUsesPerCustomer Int?\n  usedCount     Int       @default(0)\n\n  // Validity\n  startsAt   DateTime?\n  expiresAt  DateTime?\n  isAutomatic Boolean   @default(false) // no code needed\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  store  Store            @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  usages DiscountUsage[]\n\n  @@index([storeId])\n  @@map(\"discounts\")\n}\n\nmodel DiscountUsage {\n  id          String   @id @default(uuid())\n  discountId  String\n  orderId     String\n  customerId  String?\n  amountSaved Float\n  appliedAt   DateTime @default(now())\n\n  discount Discount @relation(fields: [discountId], references: [id], onDelete: Cascade)\n\n  @@index([discountId])\n  @@index([orderId])\n  @@map(\"discount_usages\")\n}\n\nenum DiscountType {\n  AUTOMATIC     // applies automatically at checkout\n  BOGO          // buy X get Y\n  TIERED        // volume tiers\n  FLASH_SALE    // time-limited\n  PERCENTAGE    // classic % off\n  FIXED         // fixed $ off\n  FREE_SHIPPING // free shipping\n  BUNDLE        // spend X get Y\n}\n\nenum DiscountStatus {\n  ACTIVE\n  PAUSED\n  EXPIRED\n  SCHEDULED\n}\n\nenum DiscountValueType {\n  PERCENTAGE\n  FIXED_AMOUNT\n  NEW_PRICE\n  FREE\n}\n\n// ─── Referral & Affiliate System ─────────────────────────────────────────────\n\nmodel Affiliate {\n  id          String          @id @default(uuid())\n  storeId     String\n  name        String\n  email       String\n  code        String          // unique referral code\n  status      AffiliateStatus @default(PENDING)\n  commissionPct Float         @default(10)  // % of order value\n  commissionFlat Float?       // flat $ per sale (override)\n  payoutMethod  String?       // \"paypal\" | \"bank\" | \"store_credit\"\n  payoutDetails Json?         // encrypted payout info\n  totalEarned   Float         @default(0)\n  totalPaid     Float         @default(0)\n  totalClicks   Int           @default(0)\n  totalOrders   Int           @default(0)\n  notes         String?\n  createdAt   DateTime        @default(now())\n  updatedAt   DateTime        @updatedAt\n\n  store     Store             @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  referrals ReferralConversion[]\n  payouts   AffiliatePayout[]\n\n  @@unique([storeId, code])\n  @@index([storeId])\n  @@map(\"affiliates\")\n}\n\nmodel ReferralConversion {\n  id          String   @id @default(uuid())\n  affiliateId String\n  orderId     String\n  storeId     String\n  orderValue  Float\n  commission  Float\n  status      String   @default(\"PENDING\")  // PENDING | APPROVED | PAID | REJECTED\n  createdAt   DateTime @default(now())\n\n  affiliate Affiliate @relation(fields: [affiliateId], references: [id], onDelete: Cascade)\n\n  @@index([affiliateId])\n  @@index([orderId])\n  @@map(\"referral_conversions\")\n}\n\nmodel AffiliatePayout {\n  id          String   @id @default(uuid())\n  affiliateId String\n  storeId     String\n  amount      Float\n  method      String\n  status      String   @default(\"PENDING\")  // PENDING | SENT | FAILED\n  reference   String?\n  note        String?\n  createdAt   DateTime @default(now())\n\n  affiliate Affiliate @relation(fields: [affiliateId], references: [id], onDelete: Cascade)\n\n  @@index([affiliateId])\n  @@map(\"affiliate_payouts\")\n}\n\n// Affiliate click tracking\nmodel ReferralClick {\n  id          String   @id @default(uuid())\n  affiliateId String\n  storeId     String\n  ip          String?\n  userAgent   String?\n  page        String?\n  converted   Boolean  @default(false)\n  createdAt   DateTime @default(now())\n\n  @@index([affiliateId])\n  @@map(\"referral_clicks\")\n}\n\nenum AffiliateStatus {\n  PENDING\n  ACTIVE\n  PAUSED\n  SUSPENDED\n}\n\n// ─── Web Push Subscriptions ──────────────────────────────────────────────────\n\nmodel PushSubscription {\n  id       String   @id @default(uuid())\n  userId   String\n  endpoint String   @unique\n  p256dh   String   // public key\n  auth     String   // auth secret\n  deviceName String?  // e.g. \"Chrome on iPhone\"\n  isActive Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@map(\"push_subscriptions\")\n}\n\n// ─── Refund & Dispute ────────────────────────────────────────────────────────\n\nenum RefundStatus {\n  PENDING\n  APPROVED\n  REJECTED\n  PROCESSED\n}\n\nenum RefundReason {\n  DAMAGED\n  NOT_RECEIVED\n  WRONG_ITEM\n  NOT_AS_DESCRIBED\n  CHANGED_MIND\n  OTHER\n}\n\nmodel Refund {\n  id          String       @id @default(uuid())\n  orderId     String\n  storeId     String\n  amount      Float\n  reason      RefundReason\n  description String?\n  status      RefundStatus @default(PENDING)\n  gatewayRef  String?      // gateway refund ID\n  processedAt DateTime?\n  adminNote   String?\n  photos      String[]     @default([])\n  createdAt   DateTime     @default(now())\n  updatedAt   DateTime     @updatedAt\n\n  order       Order        @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  store       Store        @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([orderId])\n  @@index([storeId])\n  @@map(\"refunds\")\n}\n\n// ─── Customer Accounts ───────────────────────────────────────────────────────\n\nmodel CustomerAccount {\n  id            String    @id @default(uuid())\n  storeId       String\n  email         String\n  name          String\n  phone         String?\n  passwordHash  String\n  emailVerified Boolean   @default(false)\n  verifyToken   String?\n  resetToken    String?\n  resetExpiry   DateTime?\n  refreshToken  String?\n  defaultAddress Json?\n  savedAddresses Json[]   @default([])\n  wishlist       String[] @default([]) // productIds\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  @@unique([storeId, email])\n  @@index([storeId])\n  @@map(\"customer_accounts\")\n}\n\n// ─── Wishlist ────────────────────────────────────────────────────────────────\n\nmodel Wishlist {\n  id         String   @id @default(uuid())\n  storeId    String\n  email      String\n  productId  String\n  createdAt  DateTime @default(now())\n\n  @@unique([storeId, email, productId])\n  @@index([storeId, email])\n  @@map(\"wishlists\")\n}\n\n// ─── Gift Card ───────────────────────────────────────────────────────────────\n\nmodel GiftCard {\n  id          String    @id @default(uuid())\n  storeId     String\n  code        String    @unique\n  balance     Float\n  initialAmount Float\n  currency    String    @default(\"USD\")\n  isActive    Boolean   @default(true)\n  purchasedBy String?   // email\n  assignedTo  String?   // email\n  expiresAt   DateTime?\n  note        String?\n  redeemedAmount Float  @default(0)\n  usages      GiftCardUsage[]\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  store       Store     @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@index([code])\n  @@map(\"gift_cards\")\n}\n\nmodel GiftCardUsage {\n  id         String   @id @default(uuid())\n  giftCardId String\n  orderId    String\n  amount     Float\n  createdAt  DateTime @default(now())\n\n  giftCard   GiftCard @relation(fields: [giftCardId], references: [id], onDelete: Cascade)\n\n  @@index([giftCardId])\n  @@map(\"gift_card_usages\")\n}\n\n// ─── Funnel Analytics ────────────────────────────────────────────────────────\n\nmodel FunnelEvent {\n  id        String   @id @default(uuid())\n  storeId   String\n  sessionId String\n  event     String   // \"view\" | \"add_to_cart\" | \"checkout_start\" | \"purchase\"\n  productId String?\n  orderId   String?\n  value     Float?\n  meta      Json?\n  ip        String?\n  userAgent String?\n  createdAt DateTime @default(now())\n\n  @@index([storeId])\n  @@index([sessionId])\n  @@index([event])\n  @@index([createdAt])\n  @@map(\"funnel_events\")\n}\n\n// ─── UTM / Traffic Source ────────────────────────────────────────────────────\n\nmodel UtmSession {\n  id         String   @id @default(uuid())\n  storeId    String\n  sessionId  String\n  source     String?\n  medium     String?\n  campaign   String?\n  term       String?\n  content    String?\n  landingPage String?\n  referrer   String?\n  converted  Boolean  @default(false)\n  orderId    String?\n  orderValue Float?\n  createdAt  DateTime @default(now())\n\n  @@unique([storeId, sessionId])\n  @@index([storeId])\n  @@index([source])\n  @@map(\"utm_sessions\")\n}\n\n// ─── API Keys (store owner) ─────────────────────────────────────────────────\n\nmodel ApiKey {\n  id          String    @id @default(uuid())\n  storeId     String\n  name        String\n  keyHash     String    @unique  // SHA-256 of actual key\n  keyPrefix   String             // first 8 chars for display\n  permissions String[]  @default([]) // [\"orders:read\",\"products:write\",...]\n  isActive    Boolean   @default(true)\n  lastUsedAt  DateTime?\n  expiresAt   DateTime?\n  createdAt   DateTime  @default(now())\n\n  store       Store     @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@index([keyHash])\n  @@map(\"api_keys\")\n}\n\n// ─── Store Backup ────────────────────────────────────────────────────────────\n\nmodel StoreBackup {\n  id        String   @id @default(uuid())\n  storeId   String\n  fileName  String\n  fileUrl   String\n  fileSize  Int?     // bytes\n  status    String   @default(\"PENDING\") // PENDING | READY | FAILED\n  createdAt DateTime @default(now())\n\n  store     Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@map(\"store_backups\")\n}\n\n// ─── Outgoing Webhooks (store owner) ────────────────────────────────────────\n\nmodel StoreWebhook {\n  id        String   @id @default(uuid())\n  storeId   String\n  url       String\n  events    String[] // [\"order.created\",\"order.paid\",\"product.updated\",...]\n  secret    String\n  isActive  Boolean  @default(true)\n  lastFiredAt DateTime?\n  failCount  Int     @default(0)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  store      Store            @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  deliveries WebhookDelivery[]\n\n  @@index([storeId])\n  @@map(\"store_webhooks\")\n}\n\nmodel WebhookDelivery {\n  id         String   @id @default(uuid())\n  webhookId  String\n  event      String\n  payload    Json\n  statusCode Int?\n  response   String?\n  success    Boolean  @default(false)\n  createdAt  DateTime @default(now())\n\n  webhook StoreWebhook @relation(fields: [webhookId], references: [id], onDelete: Cascade)\n\n  @@index([webhookId])\n  @@map(\"webhook_deliveries\")\n}\n\n// ─── Flash Sale ──────────────────────────────────────────────────────────────\n\nmodel FlashSale {\n  id          String   @id @default(uuid())\n  storeId     String\n  name        String\n  discountPct Float\n  productIds  String[]\n  startsAt    DateTime\n  endsAt      DateTime\n  isActive    Boolean  @default(true)\n  bannerText  String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  store       Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@map(\"flash_sales\")\n}\n\n// ─── Return / RMA ────────────────────────────────────────────────────────────\n\nenum ReturnStatus {\n  REQUESTED\n  APPROVED\n  REJECTED\n  RECEIVED\n  REFUNDED\n}\n\nmodel ReturnRequest {\n  id          String       @id @default(uuid())\n  orderId     String\n  storeId     String\n  customerEmail String\n  reason      String\n  description String?\n  photos      String[]     @default([])\n  status      ReturnStatus @default(REQUESTED)\n  trackingNumber String?\n  adminNote   String?\n  resolvedAt  DateTime?\n  createdAt   DateTime     @default(now())\n  updatedAt   DateTime     @updatedAt\n\n  order       Order        @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  store       Store        @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([orderId])\n  @@index([storeId])\n  @@map(\"return_requests\")\n}\n\n// ─── Subscription Products ───────────────────────────────────────────────────\n\nmodel ProductSubscription {\n  id            String   @id @default(uuid())\n  storeId       String\n  productId     String\n  customerEmail String\n  interval      String   // \"weekly\" | \"monthly\" | \"quarterly\"\n  intervalCount Int      @default(1)\n  price         Float\n  currency      String   @default(\"USD\")\n  discount      Float    @default(0) // % off for subscribing\n  status        String   @default(\"ACTIVE\") // ACTIVE | PAUSED | CANCELLED\n  nextBillingAt DateTime\n  stripeSubId   String?\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  @@index([storeId])\n  @@index([customerEmail])\n  @@map(\"product_subscriptions\")\n}\n\n// ─── Cohort Analytics ────────────────────────────────────────────────────────\n\nmodel CohortData {\n  id        String   @id @default(uuid())\n  storeId   String\n  cohortMonth String  // \"2025-01\"\n  totalCustomers Int @default(0)\n  day30Return    Int @default(0)\n  day60Return    Int @default(0)\n  day90Return    Int @default(0)\n  calculatedAt   DateTime @default(now())\n\n  @@unique([storeId, cohortMonth])\n  @@index([storeId])\n  @@map(\"cohort_data\")\n}\n\n// ─── KAI Chat History ─────────────────────────────────────────────────────────\n\nmodel KaiConversation {\n  id        String       @id @default(uuid())\n  userId    String\n  title     String       @default(\"New Chat\")\n  createdAt DateTime     @default(now())\n  updatedAt DateTime     @updatedAt\n  messages  KaiMessage[]\n\n  user      User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@map(\"kai_conversations\")\n}\n\nmodel KaiMessage {\n  id             String          @id @default(uuid())\n  conversationId String\n  role           String          // \"user\" | \"assistant\"\n  content        String          @db.Text\n  action         String?\n  metadata       Json?\n  createdAt      DateTime        @default(now())\n\n  conversation   KaiConversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n\n  @@index([conversationId])\n  @@map(\"kai_messages\")\n}\n\n\nmodel StoreIntegration {\n  id           String    @id @default(cuid())\n  storeId      String\n  store        Store     @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  provider     String\n  email        String?\n  password     String?\n  accessToken  String?   @db.Text\n  refreshToken String?\n  expiresAt    DateTime?\n  isActive     Boolean   @default(true)\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  @@unique([storeId, provider], name: \"storeId_provider\")\n  @@index([storeId])\n}\n\nmodel WaitlistEntry {\n  id           String   @id @default(cuid())\n  name         String\n  email        String   @unique\n  whatsapp     String?\n  spotNumber   Int      @unique\n  referralCode String   @unique\n  referredBy   String?\n  source       String?\n  ipHash       String?\n  confirmed    Boolean  @default(false)\n  createdAt    DateTime @default(now())\n\n  @@index([email])\n  @@index([referralCode])\n  @@index([spotNumber])\n}\n\nmodel Bundle {\n  id              String   @id @default(uuid())\n  storeId         String\n  store           Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  name            String\n  productIds      String[]\n  discountPercent Float    @default(10)\n  bundlePrice     Float?\n  originalPrice   Float?\n  active          Boolean  @default(true)\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n}\n\nmodel GroupBuy {\n  id              String        @id @default(uuid())\n  storeId         String\n  store           Store         @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  productId       String\n  product         Product       @relation(fields: [productId], references: [id])\n  title           String\n  description     String?\n  groupPrice      Float\n  originalPrice   Float\n  minMembers      Int\n  endsAt          DateTime\n  active          Boolean       @default(true)\n  members         GroupBuyMember[]\n  createdAt       DateTime      @default(now())\n}\n\nmodel GroupBuyMember {\n  id          String   @id @default(uuid())\n  groupBuyId  String\n  groupBuy    GroupBuy @relation(fields: [groupBuyId], references: [id], onDelete: Cascade)\n  name        String\n  email       String\n  paid        Boolean  @default(false)\n  createdAt   DateTime @default(now())\n}\n\nmodel Milestone {\n  id        String   @id @default(uuid())\n  storeId   String\n  store     Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  type      String\n  title     String\n  message   String\n  cta       Json?\n  seen      Boolean  @default(false)\n  createdAt DateTime @default(now())\n}\n\nmodel ContactMessage {\n  id        String   @id @default(uuid())\n  name      String\n  email     String\n  subject   String   @default(\"general\")\n  message   String\n  status    String   @default(\"new\")\n  createdAt DateTime @default(now())\n}\n\nmodel Referral {\n  id          String   @id @default(uuid())\n  userId      String   @unique\n  user        User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  code        String   @unique\n  clicks      Int      @default(0)\n  signups     Int      @default(0)\n  conversions Int      @default(0)\n  earned      Float    @default(0)\n  pending     Float    @default(0)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n}\n\n\n\n\n\n\n\n\n\n\n\nmodel RefreshToken {\n  id          String    @id @default(uuid())\n  userId      String\n  user        User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  token       String    @unique\n  expiresAt   DateTime\n  revokedAt   DateTime?\n  ipAddress   String?\n  userAgent   String?\n  createdAt   DateTime  @default(now())\n  @@index([userId])\n  @@map(\"refresh_tokens\")\n}\n\nmodel KaiMemory {\n  id         String   @id @default(uuid())\n  userId     String\n  storeId    String?\n  key        String\n  value      String\n  category   String   @default(\"general\")\n  confidence Float    @default(1.0)\n  lastUsed   DateTime @default(now())\n  ttl        DateTime?\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n  @@unique([userId, key])\n  @@unique([storeId, key], name: \"storeId_key\")\n  @@map(\"kai_memories\")\n}\n\nmodel KaiGoal {\n  id           String   @id @default(uuid())\n  userId       String\n  storeId      String\n  title        String\n  description  String?\n  target       Float?\n  targetValue  Float?\n  current      Float    @default(0)\n  currentValue Float    @default(0)\n  unit         String   @default(\"NGN\")\n  status       String   @default(\"active\")\n  deadline     DateTime?\n  achieved     Boolean  @default(false)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n  @@map(\"kai_goals\")\n}\n\nmodel KaiMarketCache {\n  id          String   @id @default(uuid())\n  key         String   @unique\n  data        Json\n  category    String   @default(\"general\")\n  expiresAt   DateTime\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n  @@map(\"kai_market_cache\")\n}\n\nmodel KaiPulseAlert {\n  id        String   @id @default(uuid())\n  storeId   String\n  userId    String\n  type      String\n  title     String\n  message   String\n  data      Json?\n  read      Boolean  @default(false)\n  priority  String   @default(\"normal\")\n  severity  String   @default(\"info\")\n  createdAt DateTime @default(now())\n  @@index([storeId])\n  @@index([userId])\n  @@map(\"kai_pulse_alerts\")\n}\n\nmodel KaiMorningBrief {\n  id                String   @id @default(uuid())\n  userId            String\n  storeId           String\n  content           String\n  date              DateTime @default(now())\n  delivered         Boolean  @default(false)\n  topOpportunity    String?\n  revenueLastNight  Float    @default(0)\n  @@unique([storeId, date], name: \"storeId_date\")\n  @@map(\"kai_morning_briefs\")\n}\n\nmodel KaiBrandVoice {\n  id         String   @id @default(uuid())\n  storeId    String   @unique\n  tone       String   @default(\"friendly\")\n  style      String   @default(\"conversational\")\n  keywords   String[] @default([])\n  avoidWords  String[] @default([])\n  examples    String[] @default([])\n  usesEmojis  Boolean  @default(true)\n  language    String   @default(\"en\")\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n  @@map(\"kai_brand_voices\")\n}\n\nmodel KaiSkill {\n  id          String   @id @default(uuid())\n  userId      String\n  storeId     String?\n  name        String\n  description String?\n  prompt      String\n  useCount    Int      @default(0)\n  usageCount  Int      @default(0)\n  active      Boolean  @default(true)\n  isGlobal    Boolean  @default(false)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n  @@index([userId])\n  @@map(\"kai_skills\")\n}\n\nmodel LoyaltyAccount {\n  id           String   @id @default(uuid())\n  storeId      String\n  customerId   String\n  points       Int      @default(0)\n  totalEarned  Int      @default(0)\n  totalSpent     Int      @default(0)\n  totalRedeemed  Int      @default(0)\n  tier           String   @default(\"bronze\")\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n  @@unique([storeId, customerId])\n  @@map(\"loyalty_accounts\")\n}\n\nmodel ReviewRequest {\n  id         String   @id @default(uuid())\n  orderId    String   @unique\n  storeId    String\n  customerId String?\n  email      String   @default(\"\")\n  sentAt     DateTime?\n  responded  Boolean  @default(false)\n  createdAt  DateTime @default(now())\n  @@map(\"review_requests\")\n}\n\nmodel ProfitProtectionRule {\n  id          String   @id @default(uuid())\n  storeId     String\n  name        String\n  minMargin   Float    @default(20)\n  action      String   @default(\"alert\")\n  active      Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n  @@index([storeId])\n  @@map(\"profit_protection_rules\")\n}\n","backend/src/services/forecast.service.ts":"// ============================================================\n// Revenue Forecasting Service\n// Path: backend/src/services/forecast.service.ts\n// KAI analyses trends and projects forward\n// ============================================================\nimport { PrismaClient } from \"@prisma/client\";\n\nconst prisma = new PrismaClient();\n\nexport async function generateForecast(storeId: string, apiKey: string) {\n  // Get 90 days of data\n  const since = new Date(Date.now() - 90 * 24 * 60 * 60 * 1000);\n  const orders = await prisma.order.findMany({\n    where: { storeId, status: { in: [\"COMPLETED\", \"SHIPPED\", \"DELIVERED\"] }, createdAt: { gte: since } },\n    select: { total: true, createdAt: true },\n    orderBy: { createdAt: \"asc\" },\n  });\n\n  const store = await prisma.store.findUnique({\n    where: { id: storeId },\n    select: { currency: true, country: true },\n  });\n\n  const sym = store?.currency === \"NGN\" ? \"₦\" : \"$\";\n\n  // Build weekly revenue buckets\n  const weeklyData: Record<string, number> = {};\n  for (const order of orders) {\n    const week = getWeekLabel(new Date(order.createdAt));\n    weeklyData[week] = (weeklyData[week] || 0) + Number(order.total);\n  }\n\n  const weeks = Object.entries(weeklyData).map(([week, revenue]) => ({ week, revenue }));\n  const totalRevenue = orders.reduce((s, o) => s + Number(o.total), 0);\n  const avgWeekly    = weeks.length ? totalRevenue / weeks.length : 0;\n\n  // Calculate trend\n  let trend = \"stable\";\n  if (weeks.length >= 4) {\n    const recent  = weeks.slice(-4).reduce((s, w) => s + w.revenue, 0) / 4;\n    const earlier = weeks.slice(-8, -4).reduce((s, w) => s + w.revenue, 0) / Math.max(weeks.slice(-8, -4).length, 1);\n    if (recent > earlier * 1.1) trend = \"growing\";\n    else if (recent < earlier * 0.9) trend = \"declining\";\n  }\n\n  // Ask KAI for detailed forecast\n  const response = await fetch(\"https://api.anthropic.com/v1/messages\", {\n    method: \"POST\",\n    headers: {\n      \"x-api-key\": apiKey,\n      \"anthropic-version\": \"2023-06-01\",\n      \"Content-Type\": \"application/json\",\n    },\n    body: JSON.stringify({\n      model: \"claude-haiku-4-5-20251001\",\n      max_tokens: 800,\n      messages: [{\n        role: \"user\",\n        content: `Analyse this store's revenue data and provide a 30-day forecast.\n\nWeekly revenue (last 13 weeks):\n${weeks.map(w => `${w.week}: ${sym}${Math.round(w.revenue).toLocaleString()}`).join(\"\\n\")}\n\nTotal last 90 days: ${sym}${Math.round(totalRevenue).toLocaleString()}\nAverage weekly: ${sym}${Math.round(avgWeekly).toLocaleString()}\nTrend: ${trend}\nCountry: ${store?.country || \"Nigeria\"}\n\nReturn ONLY JSON:\n{\n  \"next30DaysLow\": 850000,\n  \"next30DaysMid\": 1200000,\n  \"next30DaysHigh\": 1600000,\n  \"confidence\": 72,\n  \"trendSummary\": \"2-sentence plain text summary of the trend\",\n  \"topAction\": \"Single most impactful thing to do right now to increase revenue\",\n  \"weeklyProjections\": [\n    {\"week\": \"Week 1\", \"low\": 200000, \"mid\": 280000, \"high\": 380000},\n    {\"week\": \"Week 2\", \"low\": 210000, \"mid\": 295000, \"high\": 400000},\n    {\"week\": \"Week 3\", \"low\": 215000, \"mid\": 300000, \"high\": 410000},\n    {\"week\": \"Week 4\", \"low\": 225000, \"mid\": 325000, \"high\": 410000}\n  ],\n  \"riskFactors\": [\"risk 1\", \"risk 2\"],\n  \"opportunities\": [\"opportunity 1\", \"opportunity 2\"]\n}`,\n      }],\n    }),\n  });\n\n  let forecast: any = null;\n  if (response.ok) {\n    const data: any = await response.json();\n    const text = data.content?.[0]?.text || \"{}\";\n    try { forecast = JSON.parse(text.replace(/```json|```/g, \"\").trim()); } catch {}\n  }\n\n  return {\n    historical: { weeks, totalRevenue, avgWeekly, trend },\n    forecast: forecast || {\n      next30DaysLow: Math.round(avgWeekly * 3.5),\n      next30DaysMid: Math.round(avgWeekly * 4.5),\n      next30DaysHigh: Math.round(avgWeekly * 6),\n      confidence: 60,\n      trendSummary: trend === \"growing\" ? \"Your revenue is trending upward over the last 4 weeks.\" : \"Revenue has been consistent over the past month.\",\n      topAction: \"Run a flash sale this weekend to boost next 30 days revenue\",\n      weeklyProjections: [1,2,3,4].map(w => ({\n        week: `Week ${w}`,\n        low: Math.round(avgWeekly * 0.8),\n        mid: Math.round(avgWeekly * 1.1),\n        high: Math.round(avgWeekly * 1.5),\n      })),\n      riskFactors: [\"No paid advertising detected\", \"Low product diversity\"],\n      opportunities: [\"Launch WhatsApp broadcast this week\", \"Add 5 trending products\"],\n    },\n    currency: sym,\n  };\n}\n\nfunction getWeekLabel(date: Date): string {\n  const d = new Date(date);\n  d.setDate(d.getDate() - d.getDay());\n  return d.toLocaleDateString(\"en-NG\", { month: \"short\", day: \"numeric\" });\n}\n\n// ============================================================\n// Product Web Scraper Service\n// Path: backend/src/services/scraper.service.ts  \n// KAI + web search extracts product from any URL\n// ============================================================\nexport async function scrapeProductFromUrl(url: string, storeCountry: string, apiKey: string) {\n  const isNG  = storeCountry === \"NG\";\n  const sym   = isNG ? \"₦\" : \"$\";\n\n  const response = await fetch(\"https://api.anthropic.com/v1/messages\", {\n    method: \"POST\",\n    headers: {\n      \"x-api-key\": apiKey,\n      \"anthropic-version\": \"2023-06-01\",\n      \"Content-Type\": \"application/json\",\n    },\n    body: JSON.stringify({\n      model: \"claude-sonnet-4-20250514\",\n      max_tokens: 2000,\n      tools: [{ type: \"web_search_20250305\", name: \"web_search\" }],\n      messages: [{\n        role: \"user\",\n        content: `Extract complete product information from this URL: ${url}\n\nSearch for: ${url}\n\nReturn ONLY a JSON object with this exact structure:\n{\n  \"name\": \"Full product name\",\n  \"description\": \"2-3 paragraph product description rewritten for Nigerian/African market in plain engaging English\",\n  \"shortDescription\": \"1 sentence hook\",\n  \"originalPrice\": \"price found on the URL in USD\",\n  \"suggestedLocalPrice\": \"${isNG ? \"NGN price suggestion based on 1580 exchange rate + 60% margin\" : \"local market price\"}\",\n  \"images\": [\"image_url_1\", \"image_url_2\"],\n  \"category\": \"product category\",\n  \"tags\": [\"tag1\", \"tag2\", \"tag3\"],\n  \"variants\": [\n    {\"name\": \"Color\", \"options\": [\"Black\", \"White\"]},\n    {\"name\": \"Size\", \"options\": [\"S\", \"M\", \"L\"]}\n  ],\n  \"specifications\": {\"key1\": \"value1\", \"key2\": \"value2\"},\n  \"supplierName\": \"supplier/platform name\",\n  \"supplierUrl\": \"${url}\",\n  \"estimatedShippingDays\": 14,\n  \"weight\": \"0.5kg\",\n  \"bulletPoints\": [\"benefit 1\", \"benefit 2\", \"benefit 3\", \"benefit 4\"],\n  \"seoTitle\": \"SEO title under 60 chars\",\n  \"seoDescription\": \"Meta description under 155 chars\",\n  \"whyItSells\": \"1 sentence about why this product sells well\"\n}`,\n      }],\n    }),\n  });\n\n  if (!response.ok) throw new Error(\"Scraping failed\");\n\n  const data: any = await response.json();\n  const text = data.content?.find((b: any) => b.type === \"text\")?.text || \"{}\";\n\n  try {\n    return JSON.parse(text.replace(/```json|```/g, \"\").trim());\n  } catch {\n    throw new Error(\"Could not extract product data from that URL\");\n  }\n}\n","backend/src/services/kai.agent.service.ts":"// ============================================================\n// KAI Agent Service — Dashboard In Chat\n// Path: backend/src/services/kai.agent.service.ts\n//\n// EVERY dashboard action available through chat.\n// KAI detects intent, asks for confirmation, executes.\n// Multi-store aware — always asks which store when ambiguous.\n// ============================================================\nimport prisma from \"../lib/prisma\";\n\n// ── All actions KAI can perform ───────────────────────────────\nexport type AgentAction =\n  // Store management\n  | \"select_store\"\n  | \"get_store_info\"\n  | \"update_store_settings\"\n  | \"change_store_template\"\n  | \"toggle_store_status\"           // open/close store\n  // Products\n  | \"add_product\"\n  | \"edit_product\"\n  | \"delete_product\"\n  | \"update_product_price\"\n  | \"bulk_update_prices\"\n  | \"update_product_stock\"\n  | \"toggle_product_active\"\n  | \"duplicate_product\"\n  | \"list_products\"\n  | \"search_products\"\n  // Images\n  | \"add_product_image\"\n  | \"remove_product_image\"\n  | \"reorder_product_images\"\n  // Orders\n  | \"list_orders\"\n  | \"get_order_detail\"\n  | \"update_order_status\"\n  | \"add_order_note\"\n  | \"process_refund\"\n  | \"create_manual_order\"\n  // Inventory\n  | \"check_inventory\"\n  | \"restock_product\"\n  | \"low_stock_report\"\n  // Customers\n  | \"list_customers\"\n  | \"get_customer\"\n  | \"add_customer_note\"\n  // Coupons & Marketing\n  | \"create_coupon\"\n  | \"list_coupons\"\n  | \"delete_coupon\"\n  | \"create_flash_sale\"\n  | \"end_flash_sale\"\n  // Analytics\n  | \"get_analytics\"\n  | \"get_sales_summary\"\n  | \"get_top_products\"\n  // Shipping\n  | \"list_shipping_zones\"\n  | \"update_shipping_rate\"\n  // Settings\n  | \"update_store_name\"\n  | \"update_store_logo\"\n  | \"update_payment_settings\"\n  | \"unknown\";\n\n// ── Intent detection — maps user message to action ───────────\nexport function detectAgentAction(message: string): {\n  action: AgentAction;\n  confidence: number;\n  extractedData: Record<string, any>;\n} {\n  const m = message.toLowerCase().trim();\n\n  // ── STORE SELECTION ──────────────────────────────────────────\n  if (/which store|switch store|change store|my stores/.test(m))\n    return { action: \"select_store\", confidence: 0.95, extractedData: {} };\n\n  // ── ADD PRODUCT ───────────────────────────────────────────────\n  if (/add (a )?product|create (a )?product|new product|list (a )?product/.test(m)) {\n    const name   = extractQuoted(message) || extractAfter(message, [\"called\", \"named\", \"product\"]);\n    const price  = extractPrice(message);\n    const stock  = extractNumber(message, [\"stock\", \"units\", \"pieces\", \"qty\"]);\n    return { action: \"add_product\", confidence: 0.9, extractedData: { name, price, stock } };\n  }\n\n  // ── UPDATE PRICE ──────────────────────────────────────────────\n  if (/change (the )?price|update (the )?price|set price|price to|price of/.test(m)) {\n    const name  = extractQuoted(message);\n    const price = extractPrice(message);\n    return { action: \"update_product_price\", confidence: 0.9, extractedData: { name, price } };\n  }\n\n  // ── BULK PRICE UPDATE ─────────────────────────────────────────\n  if (/increase (all |every )?price|decrease (all |every )?price|reduce (all |every )?price|all products? (by|price)/.test(m)) {\n    const percent = extractPercent(message);\n    const amount  = extractPrice(message);\n    const direction = /increase|raise|up/.test(m) ? \"increase\" : \"decrease\";\n    return { action: \"bulk_update_prices\", confidence: 0.85, extractedData: { percent, amount, direction } };\n  }\n\n  // ── UPDATE STOCK ──────────────────────────────────────────────\n  if (/restock|update stock|set stock|stock (of|for)|add stock|units/.test(m)) {\n    const name  = extractQuoted(message);\n    const stock = extractNumber(message, [\"to\", \"stock\", \"units\", \"pieces\"]);\n    return { action: \"update_product_stock\", confidence: 0.85, extractedData: { name, stock } };\n  }\n\n  // ── DELETE PRODUCT ────────────────────────────────────────────\n  if (/delete|remove (the )?product|take down/.test(m)) {\n    const name = extractQuoted(message) || extractAfter(message, [\"delete\", \"remove\"]);\n    return { action: \"delete_product\", confidence: 0.85, extractedData: { name } };\n  }\n\n  // ── LIST PRODUCTS ─────────────────────────────────────────────\n  if (/show (my |all |)products|list (my |all |)products|what (products|items) (do i|do you)|my products/.test(m))\n    return { action: \"list_products\", confidence: 0.9, extractedData: {} };\n\n  // ── INVENTORY ─────────────────────────────────────────────────\n  if (/inventory|low stock|out of stock|stock levels|check stock/.test(m))\n    return { action: \"check_inventory\", confidence: 0.9, extractedData: {} };\n\n  // ── ORDERS ────────────────────────────────────────────────────\n  if (/show (my |all |)orders|list orders|pending orders|recent orders/.test(m))\n    return { action: \"list_orders\", confidence: 0.9, extractedData: {} };\n\n  if (/mark (as |)shipped|ship order|update order|order status|mark delivered|mark paid/.test(m)) {\n    const orderId = extractOrderId(message);\n    const status  = extractOrderStatus(message);\n    return { action: \"update_order_status\", confidence: 0.85, extractedData: { orderId, status } };\n  }\n\n  if (/refund|cancel order/.test(m)) {\n    const orderId = extractOrderId(message);\n    return { action: \"process_refund\", confidence: 0.8, extractedData: { orderId } };\n  }\n\n  // ── COUPONS ───────────────────────────────────────────────────\n  if (/create (a )?coupon|make (a )?coupon|add (a )?discount code/.test(m)) {\n    const code     = extractCode(message);\n    const discount = extractPercent(message) || extractPrice(message);\n    const type     = /percent|%/.test(m) ? \"PERCENTAGE\" : \"FIXED\";\n    return { action: \"create_coupon\", confidence: 0.9, extractedData: { code, discount, type } };\n  }\n\n  if (/show coupons|list coupons|my coupons/.test(m))\n    return { action: \"list_coupons\", confidence: 0.9, extractedData: {} };\n\n  // ── FLASH SALE ────────────────────────────────────────────────\n  if (/flash sale|run (a )?sale|start (a )?sale/.test(m)) {\n    const discount = extractPercent(message) || extractPrice(message);\n    return { action: \"create_flash_sale\", confidence: 0.85, extractedData: { discount } };\n  }\n\n  // ── ANALYTICS ─────────────────────────────────────────────────\n  if (/analytics|sales summary|how (am i|are we) doing|revenue|how much (have i|did i) make/.test(m))\n    return { action: \"get_sales_summary\", confidence: 0.9, extractedData: {} };\n\n  if (/top (selling|products)|best seller|what's selling/.test(m))\n    return { action: \"get_top_products\", confidence: 0.9, extractedData: {} };\n\n  // ── CUSTOMERS ─────────────────────────────────────────────────\n  if (/show customers|list customers|my customers|how many customers/.test(m))\n    return { action: \"list_customers\", confidence: 0.9, extractedData: {} };\n\n  // ── STORE SETTINGS ────────────────────────────────────────────\n  if (/change (my |the |store )?name|rename (my |the )?store/.test(m)) {\n    const name = extractQuoted(message) || extractAfter(message, [\"to\", \"name\"]);\n    return { action: \"update_store_name\", confidence: 0.85, extractedData: { name } };\n  }\n\n  if (/change template|switch template|use (the )?.*template|change (my |the )?theme/.test(m)) {\n    const template = extractTemplateName(message);\n    return { action: \"change_store_template\", confidence: 0.8, extractedData: { template } };\n  }\n\n  if (/close (my |the )?store|open (my |the )?store|pause (my |the )?store/.test(m)) {\n    const status = /close|pause/.test(m) ? \"INACTIVE\" : \"ACTIVE\";\n    return { action: \"toggle_store_status\", confidence: 0.9, extractedData: { status } };\n  }\n\n  if (/shipping (rate|price|zone)|change (the )?delivery/.test(m))\n    return { action: \"update_shipping_rate\", confidence: 0.8, extractedData: {} };\n\n  return { action: \"unknown\", confidence: 0, extractedData: {} };\n}\n\n// ── Execute an action against the database ────────────────────\nexport async function executeAgentAction(\n  action: AgentAction,\n  data: Record<string, any>,\n  storeId: string\n): Promise<{ success: boolean; result: any; message: string }> {\n\n  switch (action) {\n\n    case \"list_products\": {\n      const products = await prisma.product.findMany({\n        where:   { storeId },\n        select:  { id: true, name: true, price: true, stockQuantity: true, isActive: true },\n        orderBy: { createdAt: \"desc\" },\n        take:    20,\n      });\n      return {\n        success: true,\n        result:  products,\n        message: `Found ${products.length} products`,\n      };\n    }\n\n    case \"add_product\": {\n      const product = await prisma.product.create({\n        data: {\n          storeId,\n          name:          data.name || \"New Product\",\n          price:         data.price || 0,\n          stockQuantity: data.stock || 0,\n          description:   data.description || \"\",\n          isActive:      data.publish !== false,\n          images:        data.images || [],\n          category:      data.category || \"General\",\n        },\n      });\n      return { success: true, result: product, message: `Product \"${product.name}\" created` };\n    }\n\n    case \"update_product_price\": {\n      if (!data.productId && !data.name) throw new Error(\"NEED_PRODUCT\");\n      const product = await findProductByNameOrId(storeId, data.productId, data.name);\n      if (!product) throw new Error(\"PRODUCT_NOT_FOUND\");\n\n      const updated = await prisma.product.update({\n        where: { id: product.id },\n        data:  { price: data.price },\n      });\n      return { success: true, result: updated, message: `Price updated to ₦${data.price.toLocaleString()}` };\n    }\n\n    case \"bulk_update_prices\": {\n      const products = await prisma.product.findMany({ where: { storeId }, select: { id: true, price: true } });\n      if (data.percent) {\n        const multiplier = data.direction === \"increase\" ? 1 + data.percent / 100 : 1 - data.percent / 100;\n        await Promise.all(products.map(p =>\n          prisma.product.update({ where: { id: p.id }, data: { price: Math.round(Number(p.price) * multiplier) } })\n        ));\n      }\n      return { success: true, result: { count: products.length }, message: `Updated prices for ${products.length} products` };\n    }\n\n    case \"update_product_stock\": {\n      const product = await findProductByNameOrId(storeId, data.productId, data.name);\n      if (!product) throw new Error(\"PRODUCT_NOT_FOUND\");\n      const updated = await prisma.product.update({\n        where: { id: product.id },\n        data:  { stockQuantity: data.stock },\n      });\n      return { success: true, result: updated, message: `Stock updated to ${data.stock} units` };\n    }\n\n    case \"delete_product\": {\n      const product = await findProductByNameOrId(storeId, data.productId, data.name);\n      if (!product) throw new Error(\"PRODUCT_NOT_FOUND\");\n      await prisma.product.delete({ where: { id: product.id } });\n      return { success: true, result: null, message: `\"${product.name}\" deleted` };\n    }\n\n    case \"toggle_product_active\": {\n      const product = await findProductByNameOrId(storeId, data.productId, data.name);\n      if (!product) throw new Error(\"PRODUCT_NOT_FOUND\");\n      const updated = await prisma.product.update({\n        where: { id: product.id },\n        data:  { isActive: data.active },\n      });\n      return { success: true, result: updated, message: `\"${product.name}\" ${data.active ? \"activated\" : \"hidden\"}` };\n    }\n\n    case \"check_inventory\": {\n      const [outOfStock, lowStock, totalActive] = await Promise.all([\n        prisma.product.count({ where: { storeId, stockQuantity: 0, isActive: true } }),\n        prisma.product.findMany({ where: { storeId, stockQuantity: { gt: 0, lte: 5 }, isActive: true }, select: { name: true, stockQuantity: true }, orderBy: { stockQuantity: \"asc\" } }),\n        prisma.product.count({ where: { storeId, isActive: true } }),\n      ]);\n      return { success: true, result: { outOfStock, lowStock, totalActive }, message: \"Inventory checked\" };\n    }\n\n    case \"list_orders\": {\n      const filter: any = { storeId };\n      if (data.status) filter.status = data.status;\n      const orders = await prisma.order.findMany({\n        where:   filter,\n        include: { customer: { select: { name: true } }, items: { take: 1, include: { product: { select: { name: true } } } } },\n        orderBy: { createdAt: \"desc\" },\n        take:    10,\n      });\n      return { success: true, result: orders, message: `Found ${orders.length} orders` };\n    }\n\n    case \"update_order_status\": {\n      if (!data.orderId) throw new Error(\"NEED_ORDER_ID\");\n      const order = await prisma.order.update({\n        where: { id: data.orderId },\n        data:  { status: data.status },\n        include: { customer: { select: { name: true } } },\n      });\n      return { success: true, result: order, message: `Order marked as ${data.status}` };\n    }\n\n    case \"create_coupon\": {\n      const code = data.code || generateCouponCode();\n      const coupon = await prisma.coupon.create({\n        data: {\n          storeId,\n          code:          code.toUpperCase(),\n          discountType:  data.type || \"PERCENTAGE\",\n          discountValue: data.discount || 10,\n          isActive:      true,\n          usageLimit:    data.limit || null,\n          expiresAt:     data.expiresAt ? new Date(data.expiresAt) : null,\n        },\n      });\n      return { success: true, result: coupon, message: `Coupon ${coupon.code} created` };\n    }\n\n    case \"list_coupons\": {\n      const coupons = await prisma.coupon.findMany({\n        where:   { storeId, isActive: true },\n        orderBy: { createdAt: \"desc\" },\n        take:    10,\n      });\n      return { success: true, result: coupons, message: `Found ${coupons.length} active coupons` };\n    }\n\n    case \"get_sales_summary\": {\n      const now         = new Date();\n      const todayStart  = new Date(now.getFullYear(), now.getMonth(), now.getDate());\n      const monthStart  = new Date(now.getFullYear(), now.getMonth(), 1);\n      const [todayOrders, monthOrders, allOrders] = await Promise.all([\n        prisma.order.findMany({ where: { storeId, createdAt: { gte: todayStart }, status: { in: [\"COMPLETED\",\"SHIPPED\",\"DELIVERED\"] } }, select: { total: true } }),\n        prisma.order.findMany({ where: { storeId, createdAt: { gte: monthStart }, status: { in: [\"COMPLETED\",\"SHIPPED\",\"DELIVERED\"] } }, select: { total: true } }),\n        prisma.order.aggregate({ where: { storeId, status: { in: [\"COMPLETED\",\"SHIPPED\",\"DELIVERED\"] } }, _count: true, _sum: { total: true } }),\n      ]);\n      return {\n        success: true,\n        result: {\n          revenueToday:     todayOrders.reduce((s, o) => s + Number(o.total), 0),\n          revenueThisMonth: monthOrders.reduce((s, o) => s + Number(o.total), 0),\n          totalRevenue:     Number(allOrders._sum.total || 0),\n          totalOrders:      allOrders._count,\n          ordersToday:      todayOrders.length,\n        },\n        message: \"Sales summary fetched\",\n      };\n    }\n\n    case \"get_top_products\": {\n      const topItems = await prisma.orderItem.groupBy({\n        by: [\"productId\"],\n        where: { order: { storeId, status: { in: [\"COMPLETED\",\"SHIPPED\",\"DELIVERED\"] } } },\n        _sum: { quantity: true },\n        orderBy: { _sum: { quantity: \"desc\" } },\n        take: 5,\n      });\n      const products = await Promise.all(topItems.map(async t => {\n        const p = await prisma.product.findUnique({ where: { id: t.productId }, select: { name: true, price: true } });\n        return { name: p?.name, price: p?.price, unitsSold: t._sum.quantity };\n      }));\n      return { success: true, result: products, message: \"Top products fetched\" };\n    }\n\n    case \"list_customers\": {\n      const customers = await prisma.storeCustomer.findMany({\n        where: { storeId },\n        include: { orders: { select: { total: true }, where: { status: { in: [\"COMPLETED\",\"SHIPPED\",\"DELIVERED\"] } } } },\n        orderBy: { createdAt: \"desc\" },\n        take: 10,\n      });\n      return {\n        success: true,\n        result: customers.map(c => ({\n          id:         c.id,\n          name:       c.name,\n          email:      c.email,\n          phone:      c.phone,\n          orderCount: c.orders.length,\n          totalSpent: c.orders.reduce((s, o) => s + Number(o.total), 0),\n        })),\n        message: `Found ${customers.length} customers`,\n      };\n    }\n\n    case \"update_store_name\": {\n      const store = await prisma.store.update({\n        where: { id: storeId },\n        data:  { name: data.name },\n      });\n      return { success: true, result: store, message: `Store renamed to \"${data.name}\"` };\n    }\n\n    case \"toggle_store_status\": {\n      const store = await prisma.store.update({\n        where: { id: storeId },\n        data:  { status: data.status },\n      });\n      return { success: true, result: store, message: `Store is now ${data.status === \"ACTIVE\" ? \"open\" : \"closed\"}` };\n    }\n\n    case \"change_store_template\": {\n      await prisma.store.update({\n        where: { id: storeId },\n        data:  { themeSettings: { template: data.template } as any },\n      });\n      return { success: true, result: null, message: `Template changed to ${data.template}` };\n    }\n\n    default:\n      return { success: false, result: null, message: \"Action not recognised\" };\n  }\n}\n\n// ── Get all stores for a user ─────────────────────────────────\nexport async function getUserStores(userId: string) {\n  return prisma.store.findMany({\n    where:  { ownerId: userId },\n    select: {\n      id:     true,\n      name:   true,\n      slug:   true,\n      status: true,\n      _count: { select: { products: true, orders: true } },\n    },\n    orderBy: { createdAt: \"desc\" },\n  });\n}\n\n// ── Helpers ───────────────────────────────────────────────────\nasync function findProductByNameOrId(storeId: string, id?: string, name?: string) {\n  if (id) return prisma.product.findFirst({ where: { id, storeId } });\n  if (name) return prisma.product.findFirst({\n    where: { storeId, name: { contains: name, mode: \"insensitive\" } },\n  });\n  return null;\n}\n\nfunction extractQuoted(text: string): string | undefined {\n  const match = text.match(/[\"']([^\"']+)[\"']/) || text.match(/called\\s+([^\\s,]+)/i);\n  return match?.[1];\n}\n\nfunction extractAfter(text: string, keywords: string[]): string | undefined {\n  for (const kw of keywords) {\n    const match = text.match(new RegExp(`${kw}\\\\s+([\\\\w\\\\s]+?)(?:\\\\s+(?:at|for|to)|$)`, \"i\"));\n    if (match) return match[1].trim();\n  }\n}\n\nfunction extractPrice(text: string): number | undefined {\n  const match = text.match(/[₦$£]?\\s*(\\d[\\d,]*)/);\n  return match ? parseInt(match[1].replace(/,/g, \"\")) : undefined;\n}\n\nfunction extractNumber(text: string, after: string[]): number | undefined {\n  for (const kw of after) {\n    const match = text.match(new RegExp(`${kw}\\\\s+(\\\\d+)`, \"i\"));\n    if (match) return parseInt(match[1]);\n  }\n  const match = text.match(/\\b(\\d+)\\s*(?:units|pieces|pcs|qty)?\\b/);\n  return match ? parseInt(match[1]) : undefined;\n}\n\nfunction extractPercent(text: string): number | undefined {\n  const match = text.match(/(\\d+)\\s*%/);\n  return match ? parseInt(match[1]) : undefined;\n}\n\nfunction extractOrderId(text: string): string | undefined {\n  const match = text.match(/#?([a-z0-9]{8,})/i);\n  return match?.[1];\n}\n\nfunction extractOrderStatus(text: string): string {\n  if (/ship|shipped/.test(text))    return \"SHIPPED\";\n  if (/deliver|delivered/.test(text)) return \"DELIVERED\";\n  if (/paid|pay/.test(text))        return \"COMPLETED\";\n  if (/cancel/.test(text))          return \"CANCELLED\";\n  if (/process/.test(text))         return \"PROCESSING\";\n  return \"SHIPPED\";\n}\n\nfunction extractCode(text: string): string | undefined {\n  const match = text.match(/code\\s+([A-Z0-9]+)/i) || text.match(/\\b([A-Z]{3,}[0-9]*)\\b/);\n  return match?.[1];\n}\n\nfunction extractTemplateName(text: string): string {\n  const templates = [\"Lagos Noir\", \"Bold\", \"Classic\", \"Glow\", \"Circuit\", \"Runway\", \"Boutique\", \"Cozy\", \"Suya\", \"Feast\"];\n  for (const t of templates) {\n    if (text.toLowerCase().includes(t.toLowerCase())) return t;\n  }\n  return \"Bold\";\n}\n\nfunction generateCouponCode(): string {\n  return Math.random().toString(36).slice(2, 8).toUpperCase();\n}\n","backend/src/services/kai.autopilot.service.ts":"// ============================================================\n// KAI Supplier Autopilot\n// Path: backend/src/services/kai.autopilot.service.ts\n//\n// THE FULL AUTOMATION LOOP:\n//\n// 1. Order placed → CJ/Supplier notified automatically\n// 2. Supplier ships → tracking flows back automatically\n// 3. Customer gets tracking via WhatsApp + Email\n// 4. Supplier stock drops → store updates + seller alerted\n// 5. Supplier raises price → margin protected automatically\n// 6. Stock hits zero → product hidden automatically\n// 7. Morning brief includes all overnight activity\n//\n// Seller just focuses on marketing.\n// Everything else: autopilot.\n// ============================================================\nimport prisma           from \"../lib/prisma\";\nimport { getLocale }    from \"../utils/kai.locale\";\nimport { sendWhatsApp } from \"./whatsapp.service\";\n\n// ═══════════════════════════════════════════════════════════════\n// STEP 1 — ORDER PLACED → NOTIFY SUPPLIER AUTOMATICALLY\n// ═══════════════════════════════════════════════════════════════\nexport async function onOrderPaid(orderId: string): Promise<void> {\n  const order = await prisma.order.findUnique({\n    where:   { id: orderId },\n    include: {\n      store:    { include: { integrations: true } },\n      customer: true,\n      items:    { include: { product: true } },\n    },\n  });\n\n  if (!order || order.status !== \"COMPLETED\") return;\n\n  const cjIntegration = order.store.integrations?.find(i => i.provider === \"cjdropshipping\" && i.isActive);\n  const locale        = getLocale(order.store.country || \"NG\");\n\n  // Categorise items by supplier\n  const cjItems = order.items.filter(i =>\n    i.product.sourceUrl?.includes(\"cjdropshipping\") ||\n    (i.product.metadata as any)?.supplier === \"cj\"\n  );\n\n  const manualItems = order.items.filter(i => !cjItems.includes(i));\n\n  // ── Auto-fulfill CJ items ───────────────────────────────────\n  if (cjItems.length > 0 && cjIntegration) {\n    await fulfillViaCJ({\n      order,\n      items:   cjItems,\n      locale,\n      apiKey:  cjIntegration.accessToken,\n      email:   cjIntegration.email!,\n      password: cjIntegration.password!,\n    });\n  }\n\n  // ── Alert seller about manual items ────────────────────────\n  if (manualItems.length > 0) {\n    const sym = locale.currencySymbol;\n    await prisma.kaiPulseAlert.create({\n      data: {\n        storeId:    order.storeId,\n        type:       \"new_order_manual\",\n        severity:   \"info\",\n        title:      `New order needs your attention`,\n        message:    `Order #${orderId.slice(-8).toUpperCase()} — ${sym}${Number(order.total).toLocaleString()} — ${manualItems.length} item(s) need manual fulfillment:\\n${manualItems.map(i => `• ${i.product.name} × ${i.quantity}`).join(\"\\n\")}`,\n        actionable: true,\n        suggestedPrompt: `Help me fulfill order #${orderId.slice(-8).toUpperCase()}`,\n        data:       { orderId, manualItems: manualItems.map(i => ({ name: i.product.name, qty: i.quantity, sourceUrl: i.product.sourceUrl })) } as any,\n      },\n    }).catch(() => {});\n  }\n\n  // ── Send order confirmation to customer ─────────────────────\n  await sendOrderConfirmationToCustomer(order, locale);\n}\n\n// ── Actually place the CJ order ──────────────────────────────\nasync function fulfillViaCJ(params: {\n  order:    any;\n  items:    any[];\n  locale:   any;\n  apiKey:   string;\n  email:    string;\n  password: string;\n}): Promise<void> {\n  const { order, items, locale } = params;\n\n  try {\n    // Get CJ token\n    const authRes = await fetch(\"https://developers.cjdropshipping.com/api2.0/v1/authentication/getAccessToken\", {\n      method:  \"POST\",\n      headers: { \"Content-Type\": \"application/json\" },\n      body:    JSON.stringify({ email: params.email, password: params.password }),\n    });\n\n    const authData: any = await authRes.json();\n    if (!authData.data?.accessToken) throw new Error(\"CJ auth failed\");\n    const token = authData.data.accessToken;\n\n    // Place the order\n    const customer = order.customer;\n    const orderPayload = {\n      orderNumber:           order.id,\n      shippingCountryCode:   customer.country || \"NG\",\n      shippingCountry:       customer.country || \"Nigeria\",\n      shippingProvince:      customer.state   || \"\",\n      shippingCity:          customer.city    || \"\",\n      shippingAddress:       customer.address || \"\",\n      shippingCustomerName:  customer.name    || \"\",\n      shippingPhone:         customer.phone   || \"\",\n      shippingZip:           customer.zip     || \"100001\",\n      remark:                `DropOS Order — Store: ${order.store.name}`,\n      products: items.map(item => ({\n        vid:          (item.product.metadata as any)?.cjVariantId || extractCJId(item.product.sourceUrl),\n        quantity:     item.quantity,\n        shippingName: \"CJPacket Ordinary\",\n      })),\n    };\n\n    const orderRes = await fetch(\"https://developers.cjdropshipping.com/api2.0/v1/shopping/order/createOrderV2\", {\n      method:  \"POST\",\n      headers: { \"CJ-Access-Token\": token, \"Content-Type\": \"application/json\" },\n      body:    JSON.stringify(orderPayload),\n    });\n\n    const orderData: any = await orderRes.json();\n\n    if (orderData.code === 200 && orderData.data?.orderId) {\n      // Update DropOS order\n      await prisma.order.update({\n        where: { id: order.id },\n        data: {\n          fulfillmentStatus: \"FULFILLED\",\n          status:            \"PROCESSING\",\n          cjOrderId:         orderData.data.orderId,\n          fulfilledAt:       new Date(),\n        } as any,\n      });\n\n      // Alert seller silently — no action needed\n      await prisma.kaiPulseAlert.create({\n        data: {\n          storeId:    order.storeId,\n          type:       \"auto_fulfilled\",\n          severity:   \"success\",\n          title:      `Order auto-fulfilled ✅`,\n          message:    `Order #${order.id.slice(-8).toUpperCase()} (${locale.currencySymbol}${Number(order.total).toLocaleString()}) was automatically sent to CJDropshipping. Tracking will arrive in 24–48 hours.`,\n          actionable: false,\n          data:       { orderId: order.id, cjOrderId: orderData.data.orderId } as any,\n        },\n      }).catch(() => {});\n\n    } else {\n      // Auto-fulfill failed — alert seller to do it manually\n      await prisma.kaiPulseAlert.create({\n        data: {\n          storeId:    order.storeId,\n          type:       \"fulfillment_failed\",\n          severity:   \"critical\",\n          title:      `⚠️ Order needs manual fulfillment`,\n          message:    `Auto-fulfillment failed for order #${order.id.slice(-8).toUpperCase()}. Reason: ${orderData.message || \"CJ error\"}. Please fulfill this order manually.`,\n          actionable: true,\n          suggestedPrompt: `Help me manually fulfill order #${order.id.slice(-8).toUpperCase()}`,\n          data:       { orderId: order.id, error: orderData.message } as any,\n        },\n      }).catch(() => {});\n    }\n  } catch (err: any) {\n    await prisma.kaiPulseAlert.create({\n      data: {\n        storeId:    order.storeId,\n        type:       \"fulfillment_error\",\n        severity:   \"critical\",\n        title:      `⚠️ Auto-fulfillment error`,\n        message:    `Could not auto-fulfill order #${order.id.slice(-8).toUpperCase()}. Error: ${err.message}. Please check your CJ connection and fulfill manually.`,\n        actionable: true,\n        data:       { orderId: order.id } as any,\n      },\n    }).catch(() => {});\n  }\n}\n\n// ═══════════════════════════════════════════════════════════════\n// STEP 2 — ORDER SHIPPED → TRACKING TO CUSTOMER AUTOMATICALLY\n// ═══════════════════════════════════════════════════════════════\nexport async function syncAndNotifyTracking(storeId: string): Promise<number> {\n  const store = await prisma.store.findUnique({\n    where:   { id: storeId },\n    include: { integrations: true, owner: { select: { phone: true } } },\n  });\n\n  const cjIntegration = store?.integrations?.find(i => i.provider === \"cjdropshipping\" && i.isActive);\n  if (!cjIntegration) return 0;\n\n  // Get CJ token\n  const authRes = await fetch(\"https://developers.cjdropshipping.com/api2.0/v1/authentication/getAccessToken\", {\n    method:  \"POST\",\n    headers: { \"Content-Type\": \"application/json\" },\n    body:    JSON.stringify({ email: cjIntegration.email, password: cjIntegration.password }),\n  });\n  const authData: any = await authRes.json();\n  if (!authData.data?.accessToken) return 0;\n  const token = authData.data.accessToken;\n\n  // Find orders that are fulfilled but no tracking yet\n  const orders = await prisma.order.findMany({\n    where: {\n      storeId,\n      fulfillmentStatus: \"FULFILLED\",\n      trackingNumber: null,\n      cjOrderId:      { not: null },\n    } as any,\n    include: { customer: { select: { name: true, email: true, phone: true } } },\n    take: 30,\n  });\n\n  let notified = 0;\n  const locale = getLocale(store?.country || \"NG\");\n\n  for (const order of orders) {\n    try {\n      const cjOrderId = (order as any).cjOrderId;\n      const res = await fetch(`https://developers.cjdropshipping.com/api2.0/v1/shopping/order/getOrderDetail?orderId=${cjOrderId}`, {\n        headers: { \"CJ-Access-Token\": token },\n      });\n\n      const data: any = await res.json();\n      const cjOrder   = data.data;\n\n      if (!cjOrder?.trackNumber) continue; // Not shipped yet\n\n      const trackingNumber = cjOrder.trackNumber;\n      const carrier        = cjOrder.logisticName || \"CJPacket\";\n      const trackingUrl    = `https://t.17track.net/en#nums=${trackingNumber}`;\n\n      // Update order\n      await prisma.order.update({\n        where: { id: order.id },\n        data: {\n          trackingNumber,\n          carrier,\n          status:    \"SHIPPED\",\n          shippedAt: new Date(),\n        } as any,\n      });\n\n      // Notify customer via WhatsApp\n      if (order.customer?.phone) {\n        const firstName = order.customer.name?.split(\" \")[0] || \"there\";\n        await sendWhatsApp({\n          to:      order.customer.phone,\n          message: `Hi ${firstName}! 📦 Your order from ${store?.name} has shipped!\\n\\nTracking: ${trackingNumber}\\nCarrier: ${carrier}\\nTrack here: ${trackingUrl}\\n\\nEstimated delivery: 7–14 days.\\n\\nThank you for shopping with us! 🙏`,\n        }).catch(() => {});\n      }\n\n      // Notify customer via email\n      await sendTrackingEmail({\n        to:           order.customer?.email || \"\",\n        customerName: order.customer?.name || \"Customer\",\n        storeName:    store?.name || \"Store\",\n        orderId:      order.id,\n        trackingNumber,\n        carrier,\n        trackingUrl,\n      }).catch(() => {});\n\n      notified++;\n      await new Promise(r => setTimeout(r, 300));\n    } catch {}\n  }\n\n  if (notified > 0) {\n    await prisma.kaiPulseAlert.create({\n      data: {\n        storeId,\n        type:       \"tracking_synced\",\n        severity:   \"success\",\n        title:      `${notified} tracking numbers synced`,\n        message:    `${notified} customers received their tracking numbers automatically via WhatsApp and email.`,\n        actionable: false,\n        data:       { notified } as any,\n      },\n    }).catch(() => {});\n  }\n\n  return notified;\n}\n\n// ═══════════════════════════════════════════════════════════════\n// STEP 3 — SUPPLIER STOCK CHANGES → STORE UPDATES AUTOMATICALLY\n// ═══════════════════════════════════════════════════════════════\nexport async function syncSupplierStock(storeId: string): Promise<{\n  updated: number; hidden: number; alerts: string[];\n}> {\n  const store = await prisma.store.findUnique({\n    where:   { id: storeId },\n    include: { integrations: true },\n    select: { country: true, name: true, integrations: true } as any,\n  });\n\n  const locale  = getLocale((store as any)?.country || \"NG\");\n  const apiKey  = process.env.ANTHROPIC_API_KEY || \"\";\n  const updated = 0;\n  let hidden    = 0;\n  const alerts: string[] = [];\n\n  if (!apiKey) return { updated, hidden, alerts };\n\n  // Get products with CJ source URLs\n  const products = await prisma.product.findMany({\n    where: {\n      storeId, isActive: true,\n      sourceUrl: { contains: \"cjdropshipping\" },\n    },\n    select: { id: true, name: true, price: true, costPrice: true, stockQuantity: true, sourceUrl: true },\n    take: 20,\n  });\n\n  for (const product of products) {\n    if (!product.sourceUrl) continue;\n\n    try {\n      // Use KAI to check CJ product status\n      const res = await fetch(\"https://api.anthropic.com/v1/messages\", {\n        method: \"POST\",\n        headers: { \"x-api-key\": apiKey, \"anthropic-version\": \"2023-06-01\", \"Content-Type\": \"application/json\" },\n        body: JSON.stringify({\n          model: \"claude-haiku-4-5-20251001\",\n          max_tokens: 150,\n          tools: [{ type: \"web_search_20250305\", name: \"web_search\" }],\n          messages: [{\n            role: \"user\",\n            content: `Check if this CJDropshipping product is in stock and get current price: ${product.sourceUrl}\nReturn ONLY JSON: {\"inStock\": true, \"stockLevel\": \"high\", \"currentPriceUSD\": 5.99, \"found\": true}\nIf cannot verify: {\"inStock\": null, \"found\": false}`,\n          }],\n        }),\n      });\n\n      if (!res.ok) continue;\n      const data: any = await res.json();\n      const text = data.content?.find((b: any) => b.type === \"text\")?.text || \"{}\";\n\n      let info: any;\n      try { info = JSON.parse(text.replace(/```json|```/g, \"\").trim()); } catch { continue; }\n      if (!info.found) continue;\n\n      const newCostLocal = info.currentPriceUSD ? Math.round(info.currentPriceUSD * locale.exchangeRateToUSD) : null;\n      const oldCost      = Number(product.costPrice || 0);\n\n      // Handle out of stock\n      if (info.inStock === false) {\n        await prisma.product.update({ where: { id: product.id }, data: { isActive: false, stockQuantity: 0 } });\n        hidden++;\n        alerts.push(`\"${product.name}\" went out of stock at supplier — hidden from your store automatically`);\n      }\n\n      // Handle price increase >10%\n      if (newCostLocal && oldCost > 0 && newCostLocal > oldCost * 1.1) {\n        const changePct = Math.round(((newCostLocal - oldCost) / oldCost) * 100);\n        const newPrice  = Math.round(Number(product.price) * (1 + changePct / 100));\n\n        await prisma.product.update({\n          where: { id: product.id },\n          data:  { costPrice: newCostLocal, price: newPrice },\n        });\n\n        alerts.push(`\"${product.name}\" supplier cost increased ${changePct}% — your selling price auto-adjusted to protect margin`);\n      }\n\n      // Handle price drop >10%\n      if (newCostLocal && oldCost > 0 && newCostLocal < oldCost * 0.9) {\n        const savingPerUnit = oldCost - newCostLocal;\n        await prisma.product.update({ where: { id: product.id }, data: { costPrice: newCostLocal } });\n        alerts.push(`\"${product.name}\" supplier price dropped — you're now making ${locale.currencySymbol}${savingPerUnit.toLocaleString()} extra per sale`);\n      }\n\n      await new Promise(r => setTimeout(r, 1500));\n    } catch {}\n  }\n\n  // Create one consolidated alert instead of spamming\n  if (alerts.length > 0) {\n    await prisma.kaiPulseAlert.create({\n      data: {\n        storeId,\n        type:       \"supplier_sync\",\n        severity:   hidden > 0 ? \"warning\" : \"info\",\n        title:      `Supplier sync: ${alerts.length} update${alerts.length > 1 ? \"s\" : \"\"}`,\n        message:    alerts.join(\"\\n\"),\n        actionable: hidden > 0,\n        data:       { alerts, hidden } as any,\n      },\n    }).catch(() => {});\n  }\n\n  return { updated: products.length, hidden, alerts };\n}\n\n// ═══════════════════════════════════════════════════════════════\n// STEP 4 — ORDER DELIVERED → REQUEST REVIEW AUTOMATICALLY\n// ═══════════════════════════════════════════════════════════════\nexport async function onOrderDelivered(orderId: string): Promise<void> {\n  // Schedule review request for 5 days later\n  // The review job in kai.reviews.service.ts picks this up\n  await prisma.order.update({\n    where: { id: orderId },\n    data:  { deliveredAt: new Date() } as any,\n  }).catch(() => {});\n}\n\n// ═══════════════════════════════════════════════════════════════\n// STEP 5 — ORDER CONFIRMATION TO CUSTOMER\n// ═══════════════════════════════════════════════════════════════\nasync function sendOrderConfirmationToCustomer(order: any, locale: any): Promise<void> {\n  const firstName = order.customer?.name?.split(\" \")[0] || \"there\";\n  const sym       = locale.currencySymbol;\n  const itemList  = order.items.map((i: any) => `• ${i.product.name} × ${i.quantity}`).join(\"\\n\");\n\n  // WhatsApp confirmation\n  if (order.customer?.phone) {\n    await sendWhatsApp({\n      to:      order.customer.phone,\n      message: `Hi ${firstName}! ✅ Your order from ${order.store.name} is confirmed!\\n\\nOrder: #${order.id.slice(-8).toUpperCase()}\\n${itemList}\\nTotal: ${sym}${Number(order.total).toLocaleString()}\\n\\nWe'll send your tracking number as soon as it ships. 📦`,\n    }).catch(() => {});\n  }\n\n  // Email confirmation\n  const resendKey = process.env.RESEND_API_KEY;\n  if (resendKey && order.customer?.email) {\n    await fetch(\"https://api.resend.com/emails\", {\n      method:  \"POST\",\n      headers: { Authorization: `Bearer ${resendKey}`, \"Content-Type\": \"application/json\" },\n      body:    JSON.stringify({\n        from:    `${order.store.name} <noreply@droposHQ.com>`,\n        to:      [order.customer.email],\n        subject: `Order confirmed — #${order.id.slice(-8).toUpperCase()}`,\n        html:    `\n          <div style=\"font-family:sans-serif;max-width:500px;margin:0 auto;padding:24px\">\n            <h2>Order Confirmed ✅</h2>\n            <p>Hi ${firstName},</p>\n            <p>Your order from <strong>${order.store.name}</strong> is confirmed!</p>\n            <div style=\"background:#f9f9f9;padding:16px;border-radius:8px;margin:16px 0\">\n              <p><strong>Order:</strong> #${order.id.slice(-8).toUpperCase()}</p>\n              <p><strong>Items:</strong><br>${itemList.replace(/\\n/g, \"<br>\")}</p>\n              <p><strong>Total:</strong> ${sym}${Number(order.total).toLocaleString()}</p>\n            </div>\n            <p>We'll email and WhatsApp you your tracking number as soon as it ships.</p>\n            <p>Thank you for shopping with us! 🙏</p>\n          </div>\n        `,\n      }),\n    }).catch(() => {});\n  }\n}\n\nasync function sendTrackingEmail(params: {\n  to: string; customerName: string; storeName: string;\n  orderId: string; trackingNumber: string; carrier: string; trackingUrl: string;\n}): Promise<void> {\n  const resendKey = process.env.RESEND_API_KEY;\n  if (!resendKey || !params.to) return;\n\n  await fetch(\"https://api.resend.com/emails\", {\n    method:  \"POST\",\n    headers: { Authorization: `Bearer ${resendKey}`, \"Content-Type\": \"application/json\" },\n    body:    JSON.stringify({\n      from:    `${params.storeName} <noreply@droposHQ.com>`,\n      to:      [params.to],\n      subject: `Your order has shipped! 📦 Track it here`,\n      html:    `\n        <div style=\"font-family:sans-serif;max-width:500px;margin:0 auto;padding:24px\">\n          <h2>Your order has shipped! 📦</h2>\n          <p>Hi ${params.customerName.split(\" \")[0]},</p>\n          <p>Great news — your order from <strong>${params.storeName}</strong> is on its way!</p>\n          <div style=\"background:#f9f9f9;padding:16px;border-radius:8px;margin:16px 0\">\n            <p><strong>Tracking Number:</strong> ${params.trackingNumber}</p>\n            <p><strong>Carrier:</strong> ${params.carrier}</p>\n          </div>\n          <a href=\"${params.trackingUrl}\" style=\"display:inline-block;padding:12px 24px;background:#7c3aed;color:white;border-radius:8px;text-decoration:none;font-weight:600\">\n            📍 Track My Order\n          </a>\n          <p style=\"margin-top:16px;color:#888;font-size:13px\">Estimated delivery: 7–14 days from ship date.</p>\n        </div>\n      `,\n    }),\n  }).catch(() => {});\n}\n\nfunction extractCJId(url: string): string {\n  const match = url?.match(/vid=([^&]+)/) || url?.match(/\\/p\\/([a-zA-Z0-9-]+)/);\n  return match?.[1] || \"\";\n}\n","backend/src/services/kai.intelligence.service.ts":"// ============================================================\n// KAI Intelligence Services — All 9 Features\n// Path: backend/src/services/kai.intelligence.service.ts\n//\n// Dual-mode: every feature works in dashboard AND via KAI chat\n// ============================================================\nimport prisma from \"../lib/prisma\";\nimport { getLocale, localiseQuery } from \"../utils/kai.locale\";\n\nconst apiKey = () => process.env.ANTHROPIC_API_KEY || \"\";\n\n// ── Claude helper ─────────────────────────────────────────────\nasync function callClaude(prompt: string, useSearch = true, model = \"claude-haiku-4-5-20251001\", maxTokens = 1000) {\n  const body: any = {\n    model, max_tokens: maxTokens,\n    messages: [{ role: \"user\", content: prompt }],\n  };\n  if (useSearch) body.tools = [{ type: \"web_search_20250305\", name: \"web_search\" }];\n\n  const res = await fetch(\"https://api.anthropic.com/v1/messages\", {\n    method: \"POST\",\n    headers: { \"x-api-key\": apiKey(), \"anthropic-version\": \"2023-06-01\", \"Content-Type\": \"application/json\" },\n    body: JSON.stringify(body),\n  });\n  if (!res.ok) throw new Error(`Claude error: ${res.status}`);\n  const data: any = await res.json();\n  return data.content?.find((b: any) => b.type === \"text\")?.text || \"\";\n}\n\nfunction parseJSON<T>(text: string, fallback: T): T {\n  try { return JSON.parse(text.replace(/```json|```/g, \"\").trim()); }\n  catch { return fallback; }\n}\n\n// ══════════════════════════════════════════════════════════════\n// 1. AD SPY ENGINE — find winning ads globally\n// ══════════════════════════════════════════════════════════════\nexport async function runAdSpy(params: {\n  query:    string;       // product or niche\n  platform: \"tiktok\" | \"instagram\" | \"facebook\" | \"all\";\n  country:  string;\n  storeId:  string;\n}) {\n  const locale  = getLocale(params.country);\n  const country = locale.countryName;\n\n  const platformMap: Record<string, string> = {\n    tiktok:    `${locale.tiktokRegion}`,\n    instagram: `Instagram ${country}`,\n    facebook:  `Facebook ads ${country}`,\n    all:       `${locale.tiktokRegion} Instagram ${country} Facebook ${country}`,\n  };\n\n  const platformStr = platformMap[params.platform] || platformMap.all;\n\n  const text = await callClaude(`\nYou are an ad intelligence expert for ${country} ecommerce market.\n\nSearch: \"${params.query} winning ads ${platformStr} 2026\"\nAlso search: \"${params.query} viral ${country} ${new Date().toLocaleDateString(\"en\", { month: \"long\", year: \"numeric\" })}\"\n\nFind the ACTUAL winning ads and hooks being used right now in ${country} for \"${params.query}\".\nFocus on ${country}-specific content, not generic global ads.\n\nReturn ONLY JSON:\n{\n  \"query\": \"${params.query}\",\n  \"country\": \"${country}\",\n  \"platform\": \"${params.platform}\",\n  \"topHooks\": [\n    {\"hook\": \"Opening line of the ad\", \"platform\": \"TikTok\", \"engagement\": \"high\", \"whyWorks\": \"why this hook works for ${country} audience\"},\n    {\"hook\": \"...\", \"platform\": \"Instagram\", \"engagement\": \"medium\", \"whyWorks\": \"...\"},\n    {\"hook\": \"...\", \"platform\": \"Facebook\", \"engagement\": \"high\", \"whyWorks\": \"...\"},\n    {\"hook\": \"...\", \"platform\": \"TikTok\", \"engagement\": \"viral\", \"whyWorks\": \"...\"}\n  ],\n  \"winningAngles\": [\n    {\"angle\": \"Problem/solution angle\", \"description\": \"what this angle emphasises for ${country} buyers\"},\n    {\"angle\": \"Social proof angle\", \"description\": \"...\"},\n    {\"angle\": \"Urgency angle\", \"description\": \"...\"}\n  ],\n  \"topProducts\": [\n    {\"name\": \"product being heavily advertised\", \"estimatedSales\": \"high/medium/low\", \"platform\": \"TikTok\"}\n  ],\n  \"trendInsight\": \"One sentence about what's working in ${country} right now for this niche\",\n  \"bestTimeToRun\": \"When to run ads in ${country} for max results\",\n  \"avoidMistakes\": [\"common mistake ${country} sellers make with these ads\", \"mistake 2\"]\n}\n`);\n\n  const result = parseJSON(text, { query: params.query, country, topHooks: [], winningAngles: [], topProducts: [], trendInsight: \"\", bestTimeToRun: \"\", avoidMistakes: [] });\n\n  // Cache for 12 hours\n  const cacheKey = `adspy_${params.country}_${params.query.slice(0, 30)}_${params.platform}`;\n  await prisma.kaiMarketCache.upsert({\n    where:  { key: cacheKey },\n    create: { key: cacheKey, category: \"adspy\", data: result as any, expiresAt: new Date(Date.now() + 12 * 60 * 60 * 1000) },\n    update: { data: result as any, expiresAt: new Date(Date.now() + 12 * 60 * 60 * 1000), updatedAt: new Date() },\n  });\n\n  return result;\n}\n\n// ══════════════════════════════════════════════════════════════\n// 2. TIKTOK VIDEO SCRIPT GENERATOR\n// ══════════════════════════════════════════════════════════════\nexport async function generateTikTokScript(params: {\n  productName:  string;\n  productDesc?: string;\n  price:        number;\n  country:      string;\n  duration:     15 | 30 | 60;\n  angle?:       string;\n}) {\n  const locale = getLocale(params.country);\n  const sym    = locale.currencySymbol;\n  const price  = `${sym}${params.price.toLocaleString()}`;\n\n  const text = await callClaude(`\nWrite a high-converting TikTok video script for ${locale.countryName} market.\n\nProduct: ${params.productName}\nPrice: ${price}\nDuration: ${params.duration} seconds\nCountry: ${locale.countryName}\n${params.angle ? `Angle: ${params.angle}` : \"\"}\n\nWrite a script that feels native to TikTok ${locale.countryName} culture.\nUse ${locale.countryName} references, slang where appropriate.\nThe hook must grab attention in the first 2 seconds.\n\nReturn ONLY JSON:\n{\n  \"title\": \"Script title\",\n  \"duration\": ${params.duration},\n  \"hook\": \"Opening line — first 2 seconds (MAX 8 words)\",\n  \"sections\": [\n    {\"time\": \"0-3s\", \"label\": \"HOOK\", \"action\": \"what to show on screen\", \"script\": \"exact words to say or text overlay\", \"tip\": \"filming tip\"},\n    {\"time\": \"3-8s\", \"label\": \"PROBLEM\", \"action\": \"...\", \"script\": \"...\", \"tip\": \"...\"},\n    {\"time\": \"8-18s\", \"label\": \"REVEAL\", \"action\": \"...\", \"script\": \"...\", \"tip\": \"...\"},\n    {\"time\": \"18-25s\", \"label\": \"SOCIAL PROOF\", \"action\": \"...\", \"script\": \"...\", \"tip\": \"...\"},\n    {\"time\": \"25-${params.duration}s\", \"label\": \"CTA\", \"action\": \"...\", \"script\": \"...\", \"tip\": \"...\"}\n  ],\n  \"soundSuggestion\": \"Type of music that works on ${locale.tiktokRegion} for this product\",\n  \"hashtags\": [\"#relevant\", \"#nigerian\", \"#hashtags\"],\n  \"hookVariants\": [\n    \"Alternative hook A\",\n    \"Alternative hook B\",\n    \"Alternative hook C\"\n  ],\n  \"postTime\": \"Best time to post on ${locale.tiktokRegion}\",\n  \"estimatedViews\": \"What kind of reach to expect\",\n  \"proTip\": \"One ${locale.countryName}-specific tip for this ad\"\n}\n`, false); // no search needed for script writing\n\n  return parseJSON(text, { hook: \"\", sections: [], hookVariants: [], hashtags: [] });\n}\n\n// ══════════════════════════════════════════════════════════════\n// 3. DAILY TOP 10 WITH ENGAGEMENT SIGNALS\n// ══════════════════════════════════════════════════════════════\nexport async function getDailyTop10(storeId: string) {\n  const store = await prisma.store.findUnique({ where: { id: storeId }, select: { country: true } });\n  const locale = getLocale(store?.country || \"NG\");\n  const today  = new Date().toISOString().split(\"T\")[0];\n  const key    = `daily_top10_${locale.country}_${today}`;\n\n  // Return cached if exists\n  const cached = await prisma.kaiMarketCache.findUnique({ where: { key } }).catch(() => null);\n  if (cached && new Date() < cached.expiresAt) return cached.data;\n\n  const text = await callClaude(`\nFind the TOP 10 products generating the most buzz in ${locale.countryName} ecommerce TODAY.\n\nSearch: \"trending products ${locale.tiktokRegion} ${today}\"\nSearch: \"viral products ${locale.countryName} Instagram ${today}\"\nSearch: \"best selling dropshipping ${locale.countryName} ${new Date().toLocaleDateString(\"en\", { month: \"long\", year: \"numeric\" })}\"\n\nFocus ONLY on ${locale.countryName}. Real market signals, not global trends.\n\nReturn ONLY JSON array of 10:\n[{\n  \"rank\": 1,\n  \"name\": \"Product name\",\n  \"category\": \"Category\",\n  \"trendScore\": 94,\n  \"trendDirection\": \"exploding\",\n  \"engagementSignal\": \"What platform + signal shows this is trending\",\n  \"adActivity\": \"heavy/moderate/light\",\n  \"supplierCostUSD\": 5.50,\n  \"supplierCostLocal\": ${Math.round(5.5 * locale.exchangeRateToUSD)},\n  \"suggestedPriceLocal\": ${Math.round(5.5 * locale.exchangeRateToUSD * 2.5)},\n  \"marginPercent\": 60,\n  \"saturationLevel\": \"low\",\n  \"windowDays\": 14,\n  \"winningHook\": \"Best ad hook for ${locale.countryName}\",\n  \"whyNow\": \"Why this specific product is trending TODAY in ${locale.countryName}\",\n  \"targetAudience\": \"${locale.countryName} audience for this product\",\n  \"symbol\": \"${locale.currencySymbol}\"\n}]\n`);\n\n  const result = parseJSON<any[]>(text, []);\n\n  await prisma.kaiMarketCache.upsert({\n    where:  { key },\n    create: { key, category: \"daily_top10\", data: result as any, expiresAt: new Date(Date.now() + 12 * 60 * 60 * 1000) },\n    update: { data: result as any, expiresAt: new Date(Date.now() + 12 * 60 * 60 * 1000), updatedAt: new Date() },\n  }).catch(() => {});\n\n  return result;\n}\n\n// ══════════════════════════════════════════════════════════════\n// 4. PROFIT PROTECTION RULES\n// ══════════════════════════════════════════════════════════════\nexport async function getProfitRules(storeId: string) {\n  return prisma.profitProtectionRule.findMany({\n    where: { storeId, isActive: true },\n    orderBy: { createdAt: \"desc\" },\n  });\n}\n\nexport async function createProfitRule(storeId: string, rule: {\n  name:        string;\n  trigger:     \"price_rise\" | \"price_drop\" | \"out_of_stock\" | \"margin_below\" | \"margin_above\";\n  threshold:   number;\n  action:      \"alert\" | \"auto_reprice\" | \"hide_product\" | \"auto_reorder\";\n  actionValue?: number;\n}) {\n  return prisma.profitProtectionRule.create({\n    data: { storeId, ...rule, isActive: true },\n  });\n}\n\nexport async function evaluateProfitRules(storeId: string): Promise<{ triggered: any[] }> {\n  const [rules, products] = await Promise.all([\n    prisma.profitProtectionRule.findMany({ where: { storeId, isActive: true } }),\n    prisma.product.findMany({\n      where: { storeId, isActive: true },\n      select: { id: true, name: true, price: true, costPrice: true, stockQuantity: true, sourceUrl: true },\n    }),\n  ]);\n\n  const triggered: any[] = [];\n\n  for (const product of products) {\n    const price     = Number(product.price);\n    const cost      = Number(product.costPrice || 0);\n    const margin    = cost > 0 ? Math.round(((price - cost) / price) * 100) : 0;\n    const inStock   = (product.stockQuantity || 0) > 0;\n\n    for (const rule of rules) {\n      let fire = false;\n      let message = \"\";\n\n      if (rule.trigger === \"margin_below\" && margin < rule.threshold && cost > 0) {\n        fire = true;\n        message = `\"${product.name}\" margin is ${margin}% — below your ${rule.threshold}% rule`;\n      }\n      if (rule.trigger === \"out_of_stock\" && !inStock) {\n        fire = true;\n        message = `\"${product.name}\" is out of stock`;\n      }\n\n      if (fire) {\n        triggered.push({ rule, product: { id: product.id, name: product.name, margin, price, cost, inStock }, message });\n\n        // Auto-execute if action is not just alert\n        if (rule.action === \"hide_product\") {\n          await prisma.product.update({ where: { id: product.id }, data: { isActive: false } });\n        }\n        if (rule.action === \"auto_reprice\" && rule.actionValue) {\n          const newPrice = Math.round(price * (1 + rule.actionValue / 100));\n          await prisma.product.update({ where: { id: product.id }, data: { price: newPrice } });\n        }\n      }\n    }\n  }\n\n  return { triggered };\n}\n\n// ══════════════════════════════════════════════════════════════\n// 5. BULK PRODUCT IMPORT (supplier store URL)\n// ══════════════════════════════════════════════════════════════\nexport async function bulkScrapeSupplierStore(params: {\n  storeUrl: string;\n  country:  string;\n  limit?:   number;\n}) {\n  const locale = getLocale(params.country);\n  const limit  = params.limit || 20;\n\n  const text = await callClaude(`\nExtract all products from this supplier store: ${params.storeUrl}\n\nSearch for products listed at: ${params.storeUrl}\nExtract product data from this store page.\n\nGet the top ${limit} products and for each one provide pricing for ${locale.countryName} market.\nExchange rate: $1 = ${locale.currencySymbol}${locale.exchangeRateToUSD}\n\nReturn ONLY JSON array:\n[{\n  \"name\": \"Product name\",\n  \"originalPriceUSD\": 5.99,\n  \"localCost\": ${Math.round(5.99 * locale.exchangeRateToUSD)},\n  \"suggestedLocalPrice\": ${Math.round(5.99 * locale.exchangeRateToUSD * 2.5)},\n  \"marginPercent\": 60,\n  \"category\": \"Category\",\n  \"image\": \"image URL if found\",\n  \"supplierUrl\": \"direct product URL\",\n  \"rating\": 4.5,\n  \"ordersCount\": \"50000+\",\n  \"quickScore\": \"A/B/C/D/F\",\n  \"reason\": \"One line why this grade\"\n}]\n`, true, \"claude-sonnet-4-20250514\", 2000);\n\n  return parseJSON<any[]>(text, []);\n}\n\n// ══════════════════════════════════════════════════════════════\n// 6. AUTOMATIC ORDER FULFILLMENT\n// ══════════════════════════════════════════════════════════════\nexport async function checkFulfillmentStatus(storeId: string) {\n  const pendingOrders = await prisma.order.findMany({\n    where: { storeId, status: \"COMPLETED\", fulfillmentStatus: \"UNFULFILLED\" },\n    include: {\n      items: { include: { product: { select: { name: true, sourceUrl: true, metadata: true } } } },\n      customer: { select: { name: true, email: true, address: true, phone: true } },\n    },\n    orderBy: { createdAt: \"asc\" },\n    take: 20,\n  });\n\n  return pendingOrders.map(order => ({\n    id:          order.id,\n    orderNumber: order.id.slice(-8).toUpperCase(),\n    customer:    order.customer,\n    items:       order.items.map(i => ({\n      productName: i.product.name,\n      quantity:    i.quantity,\n      sourceUrl:   i.product.sourceUrl,\n      canAutoFulfill: !!i.product.sourceUrl?.includes(\"aliexpress\") || !!i.product.sourceUrl?.includes(\"cjdropshipping\"),\n    })),\n    total:       order.total,\n    createdAt:   order.createdAt,\n    daysWaiting: Math.round((Date.now() - new Date(order.createdAt).getTime()) / (1000 * 60 * 60 * 24)),\n  }));\n}\n\nexport async function markOrderFulfilling(orderId: string, trackingNumber?: string, carrier?: string) {\n  return prisma.order.update({\n    where: { id: orderId },\n    data: {\n      status:            \"SHIPPED\",\n      fulfillmentStatus: \"FULFILLED\",\n      trackingNumber:    trackingNumber || null,\n      carrier:           carrier || null,\n      shippedAt:         new Date(),\n    },\n  });\n}\n\n// ══════════════════════════════════════════════════════════════\n// 7. REAL-TIME PRICE + STOCK SYNC\n// ══════════════════════════════════════════════════════════════\nexport async function syncPricesAndStock(storeId: string): Promise<{\n  checked: number; priceChanges: any[]; stockChanges: any[];\n}> {\n  const products = await prisma.product.findMany({\n    where: { storeId, isActive: true, sourceUrl: { not: null } },\n    select: { id: true, name: true, price: true, costPrice: true, stockQuantity: true, sourceUrl: true },\n    take: 15,\n  });\n\n  const priceChanges: any[] = [];\n  const stockChanges: any[] = [];\n\n  const store = await prisma.store.findUnique({ where: { id: storeId }, select: { country: true } });\n  const locale = getLocale(store?.country || \"NG\");\n\n  for (const product of products) {\n    if (!product.sourceUrl) continue;\n    try {\n      const text = await callClaude(`\nCheck the current price and stock status of this product: ${product.sourceUrl}\n\nSearch for: \"${product.sourceUrl}\"\n\nReturn ONLY JSON:\n{\"currentPriceUSD\": 5.99, \"inStock\": true, \"stockLevel\": \"high/medium/low/out\", \"found\": true}\nIf cannot verify: {\"currentPriceUSD\": null, \"inStock\": null, \"found\": false}\n`, true, \"claude-haiku-4-5-20251001\", 200);\n\n      const data = parseJSON<any>(text, { found: false });\n      if (!data.found) continue;\n\n      const newCostLocal = data.currentPriceUSD ? Math.round(data.currentPriceUSD * locale.exchangeRateToUSD) : null;\n      const oldCost = Number(product.costPrice || 0);\n\n      if (newCostLocal && Math.abs(newCostLocal - oldCost) > oldCost * 0.08) {\n        priceChanges.push({\n          productId: product.id, productName: product.name,\n          oldCost, newCost: newCostLocal,\n          change: newCostLocal > oldCost ? \"increased\" : \"decreased\",\n          changePercent: Math.round(Math.abs(newCostLocal - oldCost) / oldCost * 100),\n          symbol: locale.currencySymbol,\n        });\n        await prisma.product.update({ where: { id: product.id }, data: { costPrice: newCostLocal } });\n      }\n\n      if (data.inStock === false && (product.stockQuantity || 0) > 0) {\n        stockChanges.push({ productId: product.id, productName: product.name, status: \"out_of_stock\" });\n        await prisma.product.update({ where: { id: product.id }, data: { stockQuantity: 0 } });\n      }\n\n      await new Promise(r => setTimeout(r, 1500));\n    } catch {}\n  }\n\n  // Create pulse alerts for significant changes\n  if (priceChanges.length > 0 || stockChanges.length > 0) {\n    await prisma.kaiPulseAlert.create({\n      data: {\n        storeId, type: \"price_sync\", severity: \"info\",\n        title: `Price/stock sync complete`,\n        message: `${priceChanges.length} price changes, ${stockChanges.length} stock changes detected`,\n        actionable: priceChanges.length > 0 || stockChanges.length > 0,\n        data: { priceChanges, stockChanges } as any,\n      },\n    }).catch(() => {});\n  }\n\n  return { checked: products.length, priceChanges, stockChanges };\n}\n\n// ══════════════════════════════════════════════════════════════\n// 8. COMPETITOR STORE SPY\n// ══════════════════════════════════════════════════════════════\nexport async function spyCompetitorStore(params: {\n  storeUrl: string;\n  country:  string;\n}) {\n  const locale = getLocale(params.country);\n\n  const text = await callClaude(`\nAnalyse this ecommerce store as a competitive intelligence expert for ${locale.countryName} market.\n\nStore URL: ${params.storeUrl}\nSearch: \"${params.storeUrl}\" site analysis products prices\nSearch: \"${params.storeUrl} reviews customers\"\n\nReturn ONLY JSON:\n{\n  \"storeName\": \"name if found\",\n  \"niche\": \"what they sell\",\n  \"country\": \"${locale.countryName}\",\n  \"estimatedMonthlyRevenue\": \"${locale.currencySymbol}X-Y\",\n  \"estimatedMonthlyOrders\": \"X-Y orders\",\n  \"trafficLevel\": \"high/medium/low\",\n  \"trafficSources\": [\"organic search\", \"instagram\", \"tiktok\"],\n  \"topProducts\": [\n    {\"name\": \"product\", \"estimatedPrice\": \"${locale.currencySymbol}X\", \"salesLevel\": \"high/medium/low\"}\n  ],\n  \"newArrivals\": [\"product recently added\"],\n  \"pricingStrategy\": \"premium/budget/mid-market\",\n  \"adActivity\": \"Are they running paid ads? Where?\",\n  \"socialPresence\": {\"instagram\": \"@handle if found\", \"tiktok\": \"@handle if found\"},\n  \"strengths\": [\"what they do well\"],\n  \"weaknesses\": [\"where they fall short\"],\n  \"opportunities\": [\"how you can beat them specifically in ${locale.countryName}\"],\n  \"estimatedAdSpend\": \"low/medium/high\",\n  \"verdict\": \"2-sentence assessment for a ${locale.countryName} competitor\"\n}\n`);\n\n  return parseJSON(text, { storeName: \"Unknown\", niche: \"\", topProducts: [], weaknesses: [], opportunities: [] });\n}\n\n// ══════════════════════════════════════════════════════════════\n// 9. SUPPLIER ALTERNATIVES FINDER\n// ══════════════════════════════════════════════════════════════\nexport async function findSupplierAlternatives(params: {\n  productName:  string;\n  currentUrl?:  string;\n  country:      string;\n  maxPriceUSD?: number;\n}) {\n  const locale = getLocale(params.country);\n  const sym    = locale.currencySymbol;\n\n  const text = await callClaude(`\nFind the best supplier alternatives for \"${params.productName}\" for a seller in ${locale.countryName}.\n\nSearch: \"${params.productName} supplier aliexpress cjdropshipping 2026\"\nSearch: \"${params.productName} wholesale ${locale.countryName} supplier\"\n${params.currentUrl ? `Current supplier: ${params.currentUrl}` : \"\"}\n${params.maxPriceUSD ? `Max budget: $${params.maxPriceUSD}` : \"\"}\n\nFind suppliers that ship to or within ${locale.countryName}.\nInclude both international (AliExpress, CJ) and local if possible.\n\nReturn ONLY JSON array of up to 5 suppliers:\n[{\n  \"supplierName\": \"Supplier name\",\n  \"type\": \"international/local\",\n  \"platform\": \"AliExpress/CJDropshipping/Local market/etc\",\n  \"priceUSD\": 4.50,\n  \"priceLocal\": ${Math.round(4.5 * locale.exchangeRateToUSD)},\n  \"currency\": \"${sym}\",\n  \"shippingDaysToCountry\": 14,\n  \"minimumOrder\": 1,\n  \"qualityScore\": 8,\n  \"reliabilityScore\": 9,\n  \"hasLocalWarehouse\": false,\n  \"url\": \"URL if available\",\n  \"whyBetter\": \"Why this is better than current supplier for ${locale.countryName}\",\n  \"verified\": true\n}]\n`);\n\n  return parseJSON<any[]>(text, []);\n}\n","backend/src/services/kai.market.service.ts":"// ============================================================\n// KAI Market Service — UPDATED WITH LOCALE ENGINE\n// Path: backend/src/services/kai.market.service.ts\n// REPLACES previous version\n// All market data fetched per country\n// ============================================================\nimport { PrismaClient }     from \"@prisma/client\";\nimport { getLocale, localiseQuery, getSeasonalContext } from \"../utils/kai.locale\";\n\nconst prisma = new PrismaClient();\n\n// ── Forex Rates ───────────────────────────────────────────────\nexport async function fetchForexRates(): Promise<Record<string, number>> {\n  const cached = await prisma.kaiMarketCache.findUnique({ where: { key: \"forex_rates\" } }).catch(() => null);\n  if (cached && new Date() < cached.expiresAt) return cached.data as any;\n\n  try {\n    const res = await fetch(\"https://open.er-api.com/v6/latest/USD\", { signal: AbortSignal.timeout(5000) });\n    if (!res.ok) throw new Error(\"API failed\");\n    const data: any = await res.json();\n    const rates = {\n      NGN: data.rates?.NGN || 1580,\n      GHS: data.rates?.GHS || 15.2,\n      KES: data.rates?.KES || 130,\n      ZAR: data.rates?.ZAR || 18.5,\n      GBP: data.rates?.GBP || 0.79,\n      EUR: data.rates?.EUR || 0.92,\n    };\n    const expiresAt = new Date(Date.now() + 60 * 60 * 1000);\n    await prisma.kaiMarketCache.upsert({\n      where: { key: \"forex_rates\" },\n      create: { key: \"forex_rates\", category: \"forex\", data: rates, expiresAt },\n      update: { data: rates, expiresAt, updatedAt: new Date() },\n    });\n    return rates;\n  } catch {\n    return { NGN: 1580, GHS: 15.2, KES: 130, ZAR: 18.5, GBP: 0.79, EUR: 0.92 };\n  }\n}\n\n// ── Get market context for a store (country-specific) ─────────\nexport async function getMarketContext(countryCode = \"NG\"): Promise<string> {\n  const locale   = getLocale(countryCode);\n  const [forex]  = await Promise.all([fetchForexRates()]);\n  const seasonal = getSeasonalContext(countryCode);\n  const usdToLocal = forex[locale.currency] || locale.exchangeRateToUSD;\n\n  const lines = [\n    `LIVE MARKET DATA — ${locale.countryName.toUpperCase()}:`,\n    `Exchange rate: $1 = ${locale.currencySymbol}${usdToLocal.toLocaleString()} | Use this for all price calculations`,\n    `Seasonal context: ${seasonal}`,\n    `Shopping platforms in ${locale.countryName}: ${locale.shoppingPlatforms.join(\", \")}`,\n    `Social platforms: ${locale.socialPlatforms.join(\", \")}`,\n    `Trending searches on: ${locale.tiktokRegion}`,\n  ];\n\n  // Add cached trending data for this country\n  const today    = new Date().toISOString().split(\"T\")[0];\n  const cacheKey = `trending_${countryCode}_${today}`;\n  const trending = await prisma.kaiMarketCache.findUnique({ where: { key: cacheKey } }).catch(() => null);\n  if ((trending?.data as any)?.products?.length > 0) {\n    lines.push(`Trending in ${locale.countryName} today: ${(trending!.data as any).products.slice(0, 5).join(\", \")}`);\n  }\n\n  return lines.join(\"\\n\");\n}\n\n// ── Daily market fetch — per country ──────────────────────────\nexport async function runDailyMarketFetch(apiKey: string): Promise<void> {\n  const countries = [\"NG\", \"GH\", \"KE\", \"ZA\", \"GB\", \"US\"];\n  const today = new Date().toISOString().split(\"T\")[0];\n\n  for (const countryCode of countries) {\n    const locale   = getLocale(countryCode);\n    const cacheKey = `trending_${countryCode}_${today}`;\n\n    // Skip if already fetched today\n    const existing = await prisma.kaiMarketCache.findUnique({ where: { key: cacheKey } }).catch(() => null);\n    if (existing) continue;\n\n    try {\n      // Build country-specific search query\n      const searchQuery = localiseQuery(\"trending products to sell online this week\", countryCode);\n\n      const response = await fetch(\"https://api.anthropic.com/v1/messages\", {\n        method: \"POST\",\n        headers: { \"x-api-key\": apiKey, \"anthropic-version\": \"2023-06-01\", \"Content-Type\": \"application/json\" },\n        body: JSON.stringify({\n          model: \"claude-haiku-4-5-20251001\",\n          max_tokens: 400,\n          tools: [{ type: \"web_search_20250305\", name: \"web_search\" }],\n          messages: [{\n            role: \"user\",\n            content: `Search: \"${searchQuery}\"\nFind products trending on ${locale.tiktokRegion} and ${locale.socialPlatforms[1]} this week.\nReturn ONLY JSON: {\"products\":[\"product1\",\"product2\",\"product3\",\"product4\",\"product5\"],\"categories\":[\"cat1\",\"cat2\"],\"summary\":\"one sentence about what's hot in ${locale.countryName} this week\"}`,\n          }],\n        }),\n      });\n\n      if (response.ok) {\n        const data: any = await response.json();\n        const textBlock = data.content?.find((b: any) => b.type === \"text\");\n        if (textBlock?.text) {\n          try {\n            const parsed = JSON.parse(textBlock.text.replace(/```json|```/g, \"\").trim());\n            await prisma.kaiMarketCache.upsert({\n              where: { key: cacheKey },\n              create: { key: cacheKey, category: \"trending\", data: parsed, expiresAt: new Date(Date.now() + 24 * 60 * 60 * 1000) },\n              update: { data: parsed, expiresAt: new Date(Date.now() + 24 * 60 * 60 * 1000), updatedAt: new Date() },\n            });\n            console.log(`[Market] ${locale.countryName}: fetched trending data`);\n          } catch {}\n        }\n      }\n\n      // Delay between countries to avoid rate limits\n      await new Promise(r => setTimeout(r, 3000));\n    } catch (err) {\n      console.error(`[Market] ${locale.countryName} fetch failed:`, err);\n    }\n  }\n\n  // Always refresh forex\n  await fetchForexRates();\n}\n\n// ── Skills for a store ────────────────────────────────────────\nexport async function getKaiSkills(storeId: string) {\n  const [storeSkills, globalSkills] = await Promise.all([\n    prisma.kaiSkill.findMany({ where: { storeId }, orderBy: [{ useCount: \"desc\" }] }),\n    prisma.kaiSkill.findMany({ where: { isGlobal: true }, orderBy: { useCount: \"desc\" }, take: 10 }),\n  ]);\n  return { storeSkills, globalSkills };\n}\n","backend/src/services/kai.memory.service.ts":"// ============================================================\n// KAI — Memory Service\n// Path: backend/src/services/kai.memory.service.ts\n// KAI remembers everything across ALL sessions forever\n// ============================================================\nimport { PrismaClient } from \"@prisma/client\";\n\nconst prisma = new PrismaClient();\n\n// ── Save a memory ─────────────────────────────────────────────\nexport async function saveMemory(\n  storeId: string,\n  category: string,\n  key: string,\n  value: string,\n  confidence = 1.0,\n  conversationId?: string\n): Promise<void> {\n  await prisma.kaiMemory.upsert({\n    where: { storeId_key: { storeId, key } },\n    create: {\n      storeId, category, key, value, confidence,\n      sourceConversationId: conversationId,\n    },\n    update: {\n      value, confidence,\n      lastUsed: new Date(),\n      sourceConversationId: conversationId,\n    },\n  });\n}\n\n// ── Get all memories for a store ──────────────────────────────\nexport async function getMemories(storeId: string, category?: string) {\n  return prisma.kaiMemory.findMany({\n    where: { storeId, ...(category && { category }) },\n    orderBy: { lastUsed: \"desc\" },\n    take: 50,\n  });\n}\n\n// ── Get memories as context string for prompt ─────────────────\nexport async function getMemoryContext(storeId: string): Promise<string> {\n  const memories = await prisma.kaiMemory.findMany({\n    where: { storeId },\n    orderBy: [{ confidence: \"desc\" }, { lastUsed: \"desc\" }],\n    take: 30,\n  });\n\n  if (memories.length === 0) return \"\";\n\n  const grouped: Record<string, typeof memories> = {};\n  for (const m of memories) {\n    if (!grouped[m.category]) grouped[m.category] = [];\n    grouped[m.category].push(m);\n  }\n\n  const lines: string[] = [\"PERSISTENT MEMORY (KAI knows this about this store):\"];\n  for (const [cat, mems] of Object.entries(grouped)) {\n    lines.push(`[${cat.replace(/_/g, \" \").toUpperCase()}]`);\n    for (const m of mems) {\n      lines.push(`  - ${m.value}`);\n    }\n  }\n\n  return lines.join(\"\\n\");\n}\n\n// ── Extract and save memories from conversation ───────────────\nexport async function extractMemoriesFromConversation(\n  storeId: string,\n  userMessage: string,\n  kaiResponse: string,\n  conversationId: string,\n  apiKey: string\n): Promise<void> {\n  // Use Claude Haiku (cheap) to extract memories\n  const response = await fetch(\"https://api.anthropic.com/v1/messages\", {\n    method: \"POST\",\n    headers: {\n      \"x-api-key\": apiKey,\n      \"anthropic-version\": \"2023-06-01\",\n      \"Content-Type\": \"application/json\",\n    },\n    body: JSON.stringify({\n      model: \"claude-haiku-4-5-20251001\",\n      max_tokens: 500,\n      messages: [{\n        role: \"user\",\n        content: `Extract business facts worth remembering from this conversation.\nReturn ONLY a JSON array. Empty array if nothing worth remembering.\n\nUser said: \"${userMessage.slice(0, 500)}\"\nKAI responded: \"${kaiResponse.slice(0, 300)}\"\n\nExtract memories like:\n- Business facts (what they sell, where they are, target market)\n- Owner preferences (what they like/dislike, how they communicate)\n- Goals they mentioned\n- Patterns they revealed (best selling day, typical customer etc)\n- Supplier notes\n- What didn't work for them\n\nFormat: [{\"category\":\"business_fact\",\"key\":\"unique_key\",\"value\":\"what to remember\",\"confidence\":0.9}]\nCategories: business_fact, owner_preference, goal, seasonal_pattern, supplier_note, customer_insight, brand_voice, failure, success\n\nReturn [] if nothing important to remember. Return raw JSON only.`,\n      }],\n    }),\n  });\n\n  if (!response.ok) return;\n\n  const data: any = await response.json();\n  const text = data.content?.[0]?.text || \"[]\";\n\n  try {\n    const memories = JSON.parse(text.replace(/```json|```/g, \"\").trim());\n    if (!Array.isArray(memories)) return;\n\n    for (const m of memories) {\n      if (m.category && m.key && m.value) {\n        await saveMemory(storeId, m.category, m.key, m.value, m.confidence || 0.8, conversationId);\n      }\n    }\n  } catch {}\n}\n\n// ── Mark memory as used ───────────────────────────────────────\nexport async function touchMemory(storeId: string, key: string): Promise<void> {\n  await prisma.kaiMemory.updateMany({\n    where: { storeId, key },\n    data: { lastUsed: new Date() },\n  });\n}\n\n// ── Delete a memory ───────────────────────────────────────────\nexport async function deleteMemory(storeId: string, key: string): Promise<void> {\n  await prisma.kaiMemory.deleteMany({ where: { storeId, key } });\n}\n\n// ── Get goals for context ─────────────────────────────────────\nexport async function getActiveGoals(storeId: string) {\n  return prisma.kaiGoal.findMany({\n    where: { storeId, status: \"active\" },\n    ,\n    orderBy: { deadline: \"asc\" },\n    take: 3,\n  });\n}\n\n// ── Update goal progress ──────────────────────────────────────\nexport async function updateGoalProgress(goalId: string, currentValue: number): Promise<void> {\n  const goal = await prisma.kaiGoal.findUnique({\n    where: { id: goalId },\n    ,\n  });\n  if (!goal) return;\n\n  const newStatus = currentValue >= goal.targetValue ? \"achieved\"\n    : new Date() > goal.deadline ? \"behind\"\n    : \"active\";\n\n  await prisma.kaiGoal.update({\n    where: { id: goalId },\n    data: { currentValue, status: newStatus, updatedAt: new Date() },\n  });\n\n  // Mark milestones achieved\n  for (const milestone of goal.milestones) {\n    if (!milestone.achieved && currentValue >= milestone.targetValue) {\n      await prisma.milestone.update({\n        where: { id: milestone.id },\n        data: { achieved: true, achievedAt: new Date() },\n      });\n    }\n  }\n}\n\n// ── Get brand voice ───────────────────────────────────────────\nexport async function getBrandVoice(storeId: string) {\n  return prisma.kaiBrandVoice.findUnique({ where: { storeId } });\n}\n\n// ── Analyze and save brand voice ──────────────────────────────\nexport async function analyzeBrandVoice(\n  storeId: string,\n  sampleContent: string,\n  apiKey: string\n): Promise<void> {\n  if (!sampleContent || sampleContent.length < 50) return;\n\n  const response = await fetch(\"https://api.anthropic.com/v1/messages\", {\n    method: \"POST\",\n    headers: {\n      \"x-api-key\": apiKey,\n      \"anthropic-version\": \"2023-06-01\",\n      \"Content-Type\": \"application/json\",\n    },\n    body: JSON.stringify({\n      model: \"claude-haiku-4-5-20251001\",\n      max_tokens: 300,\n      messages: [{\n        role: \"user\",\n        content: `Analyze this business owner's writing style and return ONLY JSON:\n\n\"${sampleContent.slice(0, 1000)}\"\n\nReturn: {\"tone\":\"formal|casual|energetic|warm|professional\",\"usesEmojis\":true|false,\"language\":\"english|pidgin|yoruba|igbo|hausa\",\"sentenceLength\":\"short|medium|long\",\"keywords\":[\"word1\",\"word2\"],\"avoidWords\":[]}\n\nRaw JSON only.`,\n      }],\n    }),\n  });\n\n  if (!response.ok) return;\n  const data: any = await response.json();\n  const text = data.content?.[0]?.text || \"{}\";\n\n  try {\n    const voice = JSON.parse(text.replace(/```json|```/g, \"\").trim());\n    await prisma.kaiBrandVoice.upsert({\n      where: { storeId },\n      create: {\n        storeId,\n        tone: voice.tone || \"casual\",\n        usesEmojis: voice.usesEmojis ?? true,\n        language: voice.language || \"english\",\n        sentenceLength: voice.sentenceLength || \"medium\",\n        keywords: voice.keywords || [],\n        avoidWords: voice.avoidWords || [],\n        sampleContent: sampleContent.slice(0, 500),\n      },\n      update: {\n        tone: voice.tone || \"casual\",\n        usesEmojis: voice.usesEmojis ?? true,\n        language: voice.language || \"english\",\n        sentenceLength: voice.sentenceLength || \"medium\",\n        keywords: voice.keywords || [],\n        avoidWords: voice.avoidWords || [],\n        sampleContent: sampleContent.slice(0, 500),\n        updatedAt: new Date(),\n      },\n    });\n  } catch {}\n}\n","backend/src/services/kai.reviews.service.ts":"// ============================================================\n// KAI — Review Request Automation\n// Path: backend/src/services/kai.reviews.service.ts\n// Triggered: 5 days after order status = DELIVERED\n// ============================================================\nimport { PrismaClient } from \"@prisma/client\";\n\nconst prisma = new PrismaClient();\n\n// ── Send review request to customer ──────────────────────────\nexport async function sendReviewRequest(orderId: string): Promise<void> {\n  try {\n    const order = await prisma.order.findUnique({\n      where: { id: orderId },\n      include: {\n        customer: { select: { id: true, name: true, email: true, phone: true } },\n        store: { select: { id: true, name: true, slug: true } },\n        items: { take: 1, include: { product: { select: { name: true } } } },\n      },\n    });\n\n    if (!order || !order.customer) return;\n\n    // Check not already sent\n    const alreadySent = await prisma.reviewRequest.findFirst({\n      where: { orderId, customerId: order.customer.id },\n    });\n    if (alreadySent) return;\n\n    const firstName    = order.customer.name?.split(\" \")[0] || \"there\";\n    const productName  = order.items[0]?.product?.name || \"your recent purchase\";\n    const storeName    = order.store.name;\n    const reviewUrl    = `https://${order.store.slug}.droposHQ.com/review/${orderId}`;\n\n    // Save review request record\n    await prisma.reviewRequest.create({\n      data: {\n        orderId,\n        customerId: order.customer.id,\n        storeId: order.store.id,\n      },\n    });\n\n    // Send email via Resend\n    await sendReviewEmail({\n      to: order.customer.email,\n      customerName: firstName,\n      productName,\n      storeName,\n      reviewUrl,\n    });\n\n    console.log(`[Review Request] Sent to ${order.customer.email} for order ${orderId}`);\n  } catch (err) {\n    console.error(\"[Review Request] Error:\", err);\n  }\n}\n\n// ── Email sending ─────────────────────────────────────────────\nasync function sendReviewEmail(params: {\n  to: string;\n  customerName: string;\n  productName: string;\n  storeName: string;\n  reviewUrl: string;\n}): Promise<void> {\n  const { RESEND_API_KEY } = process.env;\n  if (!RESEND_API_KEY) return;\n\n  await fetch(\"https://api.resend.com/emails\", {\n    method: \"POST\",\n    headers: {\n      Authorization: `Bearer ${RESEND_API_KEY}`,\n      \"Content-Type\": \"application/json\",\n    },\n    body: JSON.stringify({\n      from: `${params.storeName} <noreply@droposHQ.com>`,\n      to: [params.to],\n      subject: `How was your ${params.productName}? ⭐`,\n      html: `\n        <div style=\"font-family: sans-serif; max-width: 500px; margin: 0 auto; padding: 24px;\">\n          <h2 style=\"color: #111;\">Hi ${params.customerName} 👋</h2>\n          <p style=\"color: #444; line-height: 1.6;\">\n            How are you enjoying your <strong>${params.productName}</strong>?\n            We'd love to hear what you think — it only takes 30 seconds.\n          </p>\n          <a href=\"${params.reviewUrl}\" \n             style=\"display: inline-block; margin: 16px 0; padding: 12px 24px; background: #7c3aed; color: white; border-radius: 8px; text-decoration: none; font-weight: 600;\">\n            ⭐ Leave a Quick Review\n          </a>\n          <p style=\"color: #888; font-size: 13px;\">\n            Your feedback helps other customers and means a lot to our small business.\n          </p>\n          <p style=\"color: #888; font-size: 12px; margin-top: 24px;\">\n            — The ${params.storeName} Team\n          </p>\n        </div>\n      `,\n    }),\n  });\n}\n\n// ── Schedule check — runs every hour via cron ─────────────────\n// Called from kai.jobs.ts\nexport async function processReviewRequests(): Promise<void> {\n  const fiveDaysAgo = new Date(Date.now() - 5 * 24 * 60 * 60 * 1000);\n  const sixDaysAgo  = new Date(Date.now() - 6 * 24 * 60 * 60 * 1000);\n\n  // Find orders delivered 5-6 days ago, no review request sent yet\n  const eligibleOrders = await prisma.order.findMany({\n    where: {\n      status: \"DELIVERED\",\n      updatedAt: { gte: sixDaysAgo, lte: fiveDaysAgo },\n      // reviewRequests filter removed - use date-based filter instead\n    },\n    select: { id: true },\n    take: 50,\n  });\n\n  for (const order of eligibleOrders) {\n    await sendReviewRequest(order.id);\n    // Small delay to avoid Resend rate limits\n    await new Promise(r => setTimeout(r, 200));\n  }\n\n  if (eligibleOrders.length > 0) {\n    console.log(`[Review Requests] Processed ${eligibleOrders.length} orders`);\n  }\n}\n","backend/src/services/loyalty.service.ts":"// ============================================================\n// KAI — Customer Loyalty Points\n// Path: backend/src/services/loyalty.service.ts\n// Points earned per ₦ spent. Redeemable at checkout.\n// ============================================================\nimport { PrismaClient } from \"@prisma/client\";\n\nconst prisma = new PrismaClient();\n\n// Default: 1 point per ₦100 spent\nconst POINTS_PER_NAIRA = 0.01; // 1 point per ₦100\nconst POINT_VALUE_NAIRA = 1;   // 1 point = ₦1 discount\n\n// ── Award points after successful order ───────────────────────\nexport async function awardPoints(orderId: string): Promise<void> {\n  const order = await prisma.order.findUnique({\n    where: { id: orderId },\n    include: { store: { select: { id: true, loyaltyEnabled: true } }, customer: true },\n  });\n\n  if (!order?.customer || !order.store.loyaltyEnabled) return;\n\n  const pointsEarned = Math.floor(Number(order.total) * POINTS_PER_NAIRA);\n  if (pointsEarned <= 0) return;\n\n  // Upsert loyalty account\n  const existing = await prisma.loyaltyAccount.findFirst({\n    where: { customerId: order.customer.id, storeId: order.store.id },\n  });\n\n  if (existing) {\n    await prisma.loyaltyAccount.update({\n      where: { id: existing.id },\n      data: {\n        points: { increment: pointsEarned },\n        totalEarned: { increment: pointsEarned },\n        transactions: {\n          create: {\n            type: \"EARN\",\n            points: pointsEarned,\n            description: `Earned from order #${orderId.slice(-8).toUpperCase()}`,\n            orderId,\n          },\n        },\n      },\n    });\n  } else {\n    await prisma.loyaltyAccount.create({\n      data: {\n        customerId: order.customer.id,\n        storeId: order.store.id,\n        points: pointsEarned,\n        totalEarned: pointsEarned,\n        tier: \"bronze\",\n        transactions: {\n          create: {\n            type: \"EARN\",\n            points: pointsEarned,\n            description: `Earned from order #${orderId.slice(-8).toUpperCase()}`,\n            orderId,\n          },\n        },\n      },\n    });\n  }\n\n  // Check VIP tier upgrade\n  await checkTierUpgrade(order.customer.id, order.store.id);\n  console.log(`[Loyalty] Awarded ${pointsEarned} points to ${order.customer.name}`);\n}\n\n// ── Redeem points at checkout ─────────────────────────────────\nexport async function redeemPoints(params: {\n  customerId: string;\n  storeId: string;\n  pointsToRedeem: number;\n  orderId: string;\n}): Promise<{ success: boolean; discountAmount: number; remainingPoints: number }> {\n  const { customerId, storeId, pointsToRedeem, orderId } = params;\n\n  const account = await prisma.loyaltyAccount.findFirst({\n    where: { customerId, storeId },\n  });\n\n  if (!account || account.points < pointsToRedeem) {\n    return { success: false, discountAmount: 0, remainingPoints: account?.points || 0 };\n  }\n\n  const discountAmount = pointsToRedeem * POINT_VALUE_NAIRA;\n\n  await prisma.loyaltyAccount.update({\n    where: { id: account.id },\n    data: {\n      points: { decrement: pointsToRedeem },\n      totalRedeemed: { increment: pointsToRedeem },\n      transactions: {\n        create: {\n          type: \"REDEEM\",\n          points: -pointsToRedeem,\n          description: `Redeemed for ₦${discountAmount} discount`,\n          orderId,\n        },\n      },\n    },\n  });\n\n  return {\n    success: true,\n    discountAmount,\n    remainingPoints: account.points - pointsToRedeem,\n  };\n}\n\n// ── Get customer loyalty status ───────────────────────────────\nexport async function getLoyaltyStatus(customerId: string, storeId: string) {\n  const account = await prisma.loyaltyAccount.findFirst({\n    where: { customerId, storeId },\n    include: { transactions: { orderBy: { createdAt: \"desc\" }, take: 10 } },\n  });\n\n  if (!account) {\n    return {\n      points: 0, tier: \"bronze\", totalEarned: 0, totalRedeemed: 0,\n      pointsValue: 0, nextTier: \"silver\", pointsToNextTier: 500, transactions: [],\n    };\n  }\n\n  const tiers = [\n    { name: \"bronze\", min: 0,    max: 499,  perks: \"1 point per ₦100\" },\n    { name: \"silver\", min: 500,  max: 1999, perks: \"1.5x points, early access to sales\" },\n    { name: \"gold\",   min: 2000, max: 4999, perks: \"2x points, free shipping on orders over ₦10k\" },\n    { name: \"vip\",    min: 5000, max: Infinity, perks: \"3x points, dedicated support, exclusive prices\" },\n  ];\n\n  const currentTier = tiers.find(t => account.totalEarned >= t.min && account.totalEarned <= t.max) || tiers[0];\n  const nextTier = tiers[tiers.indexOf(currentTier) + 1];\n\n  return {\n    points: account.points,\n    tier: account.tier,\n    totalEarned: account.totalEarned,\n    totalRedeemed: account.totalRedeemed,\n    pointsValue: account.points * POINT_VALUE_NAIRA,\n    currentTierPerks: currentTier.perks,\n    nextTier: nextTier?.name || null,\n    pointsToNextTier: nextTier ? Math.max(0, nextTier.min - account.totalEarned) : 0,\n    transactions: account.transactions,\n  };\n}\n\n// ── Check and upgrade tier ────────────────────────────────────\nasync function checkTierUpgrade(customerId: string, storeId: string): Promise<void> {\n  const account = await prisma.loyaltyAccount.findFirst({\n    where: { customerId, storeId },\n  });\n  if (!account) return;\n\n  const newTier = account.totalEarned >= 5000 ? \"vip\"\n    : account.totalEarned >= 2000 ? \"gold\"\n    : account.totalEarned >= 500 ? \"silver\"\n    : \"bronze\";\n\n  if (newTier !== account.tier) {\n    await prisma.loyaltyAccount.update({\n      where: { id: account.id },\n      data: { tier: newTier },\n    });\n  }\n}\n","backend/src/services/push.service.ts":"// src/services/push.service.ts\nimport webpush from \"web-push\";\nimport { prisma } from \"../config/database\";\n\n// VAPID keys — set these in .env\n// Generate with: npx web-push generate-vapid-keys\nconst VAPID_PUBLIC  = process.env.VAPID_PUBLIC_KEY  || \"\";\nconst VAPID_PRIVATE = process.env.VAPID_PRIVATE_KEY || \"\";\nconst VAPID_EMAIL   = process.env.VAPID_EMAIL       || \"mailto:push@dropos.io\";\n\nif (VAPID_PUBLIC && VAPID_PRIVATE) {\n  webpush.setVapidDetails(VAPID_EMAIL, VAPID_PUBLIC, VAPID_PRIVATE);\n}\n\n// ── Payload shapes ────────────────────────────────────────────────────────────\nexport interface PushPayload {\n  title:   string;\n  body:    string;\n  icon?:   string;\n  badge?:  string;\n  url?:    string;\n  tag?:    string;\n  image?:  string;\n  actions?: { action: string; title: string }[];\n}\n\n// ── Send to one subscription ──────────────────────────────────────────────────\nasync function sendToSubscription(sub: any, payload: PushPayload): Promise<boolean> {\n  try {\n    await webpush.sendNotification(\n      { endpoint: sub.endpoint, keys: { p256dh: sub.p256dh, auth: sub.auth } },\n      JSON.stringify(payload),\n      { TTL: 60 * 60 * 24 }  // 24h TTL\n    );\n    return true;\n  } catch (err: any) {\n    if (err.statusCode === 410 || err.statusCode === 404) {\n      // Subscription expired — remove it\n      await prisma.pushSubscription.updateMany({\n        where: { endpoint: sub.endpoint },\n        data:  { isActive: false },\n      });\n    }\n    return false;\n  }\n}\n\n// ── Send to all subscriptions for a user ─────────────────────────────────────\nexport async function pushToUser(userId: string, payload: PushPayload): Promise<number> {\n  if (!VAPID_PUBLIC || !VAPID_PRIVATE) return 0;\n\n  const subs = await prisma.pushSubscription.findMany({\n    where: { userId, isActive: true },\n  });\n\n  const results = await Promise.allSettled(\n    subs.map(s => sendToSubscription(s, payload))\n  );\n  return results.filter(r => r.status === \"fulfilled\" && r.value).length;\n}\n\n// ── Send to all store owner subs ──────────────────────────────────────────────\nexport async function pushToStoreOwner(storeId: string, payload: PushPayload): Promise<number> {\n  const store = await prisma.store.findUnique({ where: { id: storeId }, select: { ownerId: true } });\n  if (!store) return 0;\n  return pushToUser(store.ownerId, payload);\n}\n\n// ── Pre-built notification templates ────────────────────────────────────────\nexport const PushTemplates = {\n  newOrder: (orderRef: string, amount: string) => ({\n    title:   \"💰 New Order!\",\n    body:    `Order ${orderRef} — ${amount}`,\n    tag:     \"new-order\",\n    url:     \"/dashboard/orders\",\n    icon:    \"/icons/icon-192.png\",\n  }),\n\n  lowStock: (productName: string, qty: number) => ({\n    title:   \"⚠️ Low Stock Alert\",\n    body:    `${productName} has only ${qty} units left`,\n    tag:     \"low-stock\",\n    url:     \"/dashboard/inventory\",\n    icon:    \"/icons/icon-192.png\",\n  }),\n\n  abandonedCart: (count: number) => ({\n    title:   \"🛒 Abandoned Carts\",\n    body:    `${count} cart${count > 1 ? \"s\" : \"\"} abandoned in the last 24h — recover them now`,\n    tag:     \"abandoned-carts\",\n    url:     \"/dashboard/abandoned-carts\",\n    icon:    \"/icons/icon-192.png\",\n  }),\n\n  reviewReceived: (productName: string, rating: number) => ({\n    title:   `⭐ New ${rating}-star Review`,\n    body:    `Someone left a review on \"${productName}\"`,\n    tag:     \"review\",\n    url:     \"/dashboard/reviews\",\n    icon:    \"/icons/icon-192.png\",\n  }),\n\n  payoutReady: (amount: string) => ({\n    title:   \"💸 Payout Ready\",\n    body:    `${amount} commission payout is ready to be claimed`,\n    tag:     \"payout\",\n    url:     \"/dashboard/billing\",\n    icon:    \"/icons/icon-192.png\",\n  }),\n\n  flashSaleLive: (saleName: string) => ({\n    title:   \"🔥 Flash Sale Live\",\n    body:    `Your \"${saleName}\" flash sale has started — share it now!`,\n    tag:     \"flash-sale\",\n    url:     \"/dashboard/discounts\",\n    icon:    \"/icons/icon-192.png\",\n  }),\n\n  dailySummary: (revenue: string, orders: number) => ({\n    title:   \"📊 Today's Summary\",\n    body:    `${orders} orders · ${revenue} revenue`,\n    tag:     \"daily-summary\",\n    url:     \"/dashboard/analytics\",\n    icon:    \"/icons/icon-192.png\",\n  }),\n};\n","backend/tsconfig.json":"{\n  \"compilerOptions\": {\n    \"target\": \"ES2020\",\n    \"module\": \"commonjs\",\n    \"lib\": [\n      \"ES2020\"\n    ],\n    \"outDir\": \"./dist\",\n    \"rootDir\": \"./src\",\n    \"strict\": false,\n    \"esModuleInterop\": true,\n    \"skipLibCheck\": true,\n    \"forceConsistentCasingInFileNames\": true,\n    \"resolveJsonModule\": true,\n    \"declaration\": true,\n    \"declarationMap\": true,\n    \"sourceMap\": true,\n    \"experimentalDecorators\": true,\n    \"emitDecoratorMetadata\": true,\n    \"paths\": {\n      \"@/*\": [\n        \"./src/*\"\n      ]\n    },\n    \"baseUrl\": \".\",\n    \"noImplicitAny\": false,\n    \"noEmitOnError\": false,\n    \"strictNullChecks\": false\n  },\n  \"include\": [\n    \"src/**/*\",\n    \"prisma/seed.ts\"\n  ],\n  \"exclude\": [\n    \"node_modules\",\n    \"dist\",\n    \"prisma\",\n    \"src/utils/app.additions.ts\"\n  ]\n}"};
let n=0;
for(const [rel,content] of Object.entries(files)){
  const p=rel.replace(/\//g,path.sep);
  fs.mkdirSync(path.dirname(p),{recursive:true});
  fs.writeFileSync(p,content,'utf8');
  console.log('OK',rel.split('/').slice(-2).join('/'));n++;
}
console.log('Written:',n,'files');
try{
  execSync('git add .',{stdio:'inherit'});
  const st=execSync('git status --short',{encoding:'utf8'}).trim();
  if(st){
    execSync('git commit -m "fix: Add all missing schema fields (severity, category, totalRedeemed, carrier, metadata, etc) + fix service field name mismatches"',{stdio:'inherit'});
    execSync('git push origin main',{stdio:'inherit'});
    console.log('Pushed.');
  }else{console.log('Nothing to commit');}
}catch(e){console.log('Git:',e.message);}
